INSERT INTO public.blog_posts (translation_key, locale, slug, status, title, meta_title, description, category, cover_url, cover_width, cover_height, author, reading_minutes, answer, key_takeaways, sections, faqs, related_links, published_at, content_updated_at)
VALUES
('chi-phi-thiet-ke-landing-page', 'vi', 'chi-phi-thiet-ke-landing-page', 'published', 'Chi phí thiết kế landing page gồm những gì? Cách tính và checklist', 'Chi phí thiết kế landing page', 'Các khoản chi phí khi làm landing page: thiết kế, nội dung, tên miền, hosting, bảo trì. So sánh trả một lần và gói tháng, kèm checklist chọn đơn vị.', 'Chi phí', '/blog/covers/project-4.jpg', 876, 493, 'Đội ngũ Nextchain', 6, 'Chi phí thiết kế landing page gồm phí thiết kế – nội dung – lập trình, tên miền và hosting (hằng năm) và chi phí chỉnh sửa, bảo trì về sau. Có hai cách trả: trả một lần rồi tự lo duy trì, hoặc gói tháng đã bao gồm thiết kế, hosting, cập nhật và bảo trì — cách Nextchain.site đang áp dụng, từ 249.000đ/tháng, không phí khởi tạo.', '["Đừng chỉ so sánh giá thiết kế — hãy hỏi rõ tên miền, hosting, số lần chỉnh sửa và thời gian hỗ trợ.","Landing page cho chiến dịch ngắn hạn có thể chọn gói cơ bản; trang chạy quảng cáo lâu dài nên đầu tư tracking và tối ưu chuyển đổi.","Chi phí quảng cáo là khoản riêng, không nằm trong giá thiết kế."]'::jsonb, '[{"heading":"Chi phí landing page gồm những khoản nào?","bullets":["Thiết kế giao diện: bố cục, màu sắc, hình ảnh theo thương hiệu.","Nội dung: tiêu đề, lợi ích, lời kêu gọi hành động. Nhiều đơn vị tính riêng phần viết nội dung.","Lập trình và responsive: hiển thị tốt trên điện thoại, tốc độ tải nhanh.","Tích hợp: form, Zalo, Google Analytics, pixel quảng cáo, công cụ email marketing.","Tên miền và hosting: trả theo năm, thường được tính riêng hoặc gộp trong gói duy trì.","Chỉnh sửa và bảo trì: số lần sửa miễn phí, thời gian hỗ trợ sau bàn giao."]},{"heading":"Mỗi khoản chi phí trả cho việc gì?","table":{"head":["Khoản","Trả khi nào","Ghi chú"],"rows":[["Thiết kế & nội dung","Một lần khi bắt đầu","Gồm bố cục, viết nội dung, số phương án thiết kế"],["Tên miền","Hằng năm","Hỏi rõ tên miền đăng ký dưới tên ai"],["Hosting & SSL","Hằng tháng/năm","Ảnh hưởng tốc độ và độ ổn định"],["Chỉnh sửa, cập nhật","Mỗi lần hoặc theo gói","Số lượt miễn phí và thời gian xử lý"],["Bảo trì, sao lưu","Định kỳ","Thường bị bỏ quên khi trả một lần"]]}},{"heading":"Nextchain.site tính phí landing page thế nào?","paragraphs":["Nextchain.site bán landing page theo gói tháng từ 249.000đ, không phí khởi tạo. Phí tháng đã gồm thiết kế, soạn nội dung, hosting, SSL, bảo trì và số lượt chỉnh sửa theo gói. Về tên miền, bạn dùng miễn phí địa chỉ ten-cua-ban.nextchain.site hoặc tự mua tên miền riêng để Nextchain kết nối. Gói Khởi đầu 249.000đ/tháng phù hợp một landing page; gói Tăng trưởng 790.000đ/tháng cho website đến 5 trang có blog."]},{"heading":"Vì sao cùng là landing page mà giá chênh lệch nhiều?","paragraphs":["Một landing page dựng từ mẫu có sẵn và một landing page thiết kế riêng có khối lượng công việc rất khác nhau. Các yếu tố làm thay đổi giá: mức độ tùy biến giao diện, ai viết nội dung, số lượng hiệu ứng, số công cụ cần tích hợp và thời gian hỗ trợ sau bàn giao.","Giá rẻ không sai, nhưng hãy kiểm tra trang có tải nhanh trên điện thoại không, form có gửi thông báo về đúng nơi không, và bạn có quyền với tên miền hay không."]},{"heading":"Trả một lần hay theo tháng?","paragraphs":["Nếu landing page chỉ dùng cho một chiến dịch, trả một lần là đủ. Nếu trang là kênh nhận khách lâu dài và cần thay đổi nội dung thường xuyên (giá, khuyến mãi, hình ảnh), gói quản trị theo tháng giúp bạn không phải tự xử lý kỹ thuật."]},{"heading":"Checklist trước khi chọn đơn vị làm landing page","bullets":["Giá đã gồm tên miền, hosting, SSL chưa?","Bao nhiêu lần chỉnh sửa miễn phí? Sau đó tính phí thế nào?","Ai viết nội dung? Có cần bạn chuẩn bị sẵn không?","Có gắn Google Analytics và đo sự kiện gửi form không?","Tên miền đăng ký dưới tên ai?"]}]'::jsonb, '[{"q":"Vì sao có đơn vị làm landing page rất rẻ?","a":"Thường do dùng mẫu có sẵn, không viết nội dung, ít lượt chỉnh sửa hoặc chưa tính tên miền, hosting và bảo trì. Hãy so sánh tổng chi phí trong 1–2 năm thay vì chỉ giá ban đầu."},{"q":"Giá landing page đã gồm chạy quảng cáo chưa?","a":"Chưa. Ngân sách quảng cáo trả cho Google hoặc Meta là khoản riêng."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"Dịch vụ thiết kế landing page"},{"href":"/bang-gia","label":"Bảng giá tất cả dịch vụ"},{"href":"/blog/landing-page-khac-website-doanh-nghiep","label":"Landing page khác website doanh nghiệp thế nào?"}]'::jsonb, '2026-10-13', NULL),
('chi-phi-thiet-ke-landing-page', 'ko', 'landing-page-design-cost', 'published', '랜딩페이지 제작 비용에는 무엇이 포함될까요? 계산 방법과 체크리스트', '랜딩페이지 제작 비용', '랜딩페이지를 만들 때 드는 비용을 디자인, 콘텐츠, 도메인, 호스팅, 유지보수로 나누어 살펴봅니다. 일시 결제와 월 구독을 비교하고, 제작 업체를 고르는 체크리스트도 담았습니다.', '비용', '/blog/covers/project-4.jpg', 876, 493, '넥스트체인 팀', 6, '랜딩페이지 제작 비용은 디자인·콘텐츠·개발비, 도메인과 호스팅 비용(매년 발생), 이후의 수정·유지보수 비용으로 구성됩니다. 결제 방식은 한 번에 지불하고 운영은 직접 맡는 방법과, 디자인·호스팅·업데이트·유지보수가 포함된 월 구독 방법이 있습니다. 넥스트체인은 월 구독 방식으로, 월 39,000원부터 시작하며 초기 제작비가 없습니다.', '["디자인 가격만 비교하지 말고 도메인, 호스팅, 수정 횟수, 지원 기간을 꼭 물어보세요.","단기 캠페인용 랜딩페이지는 기본 플랜으로 충분할 수 있습니다. 광고를 오래 집행할 페이지라면 추적 설정과 전환율 개선에도 투자하는 것이 좋습니다.","광고비는 별도 비용이며 제작 비용에 포함되지 않습니다."]'::jsonb, '[{"heading":"랜딩페이지 비용에는 어떤 항목이 있나요?","bullets":["디자인: 브랜드에 맞춘 레이아웃, 색상, 이미지.","콘텐츠: 제목, 장점 소개, 행동 유도 문구. 글 작성을 별도로 청구하는 업체가 많습니다.","개발과 반응형 처리: 모바일에서 잘 보이고 빠르게 열리는 페이지.","연동: 문의 폼, 카카오톡 채널, 구글 애널리틱스, 광고 픽셀, 이메일 마케팅 도구.","도메인과 호스팅: 연 단위로 결제하며, 별도 청구하거나 유지 플랜에 포함하는 경우가 많습니다.","수정과 유지보수: 무상 수정 횟수, 인도 후 지원 기간."]},{"heading":"각 비용은 무엇에 대한 대가인가요?","table":{"head":["항목","결제 시기","참고"],"rows":[["디자인·콘텐츠","시작할 때 1회","레이아웃, 글 작성, 디자인 시안 수 포함 여부 확인"],["도메인","매년","도메인이 누구 명의로 등록되는지 꼭 확인"],["호스팅·SSL","매월 또는 매년","속도와 안정성에 영향"],["수정·업데이트","건별 또는 플랜별","무상 수정 횟수와 처리 시간 확인"],["유지보수·백업","정기","일시 결제 시 가장 자주 빠지는 항목"]]}},{"heading":"넥스트체인은 랜딩페이지 비용을 어떻게 받나요?","paragraphs":["넥스트체인은 랜딩페이지를 월 39,000원부터 월 구독으로 제공하며 초기 제작비는 없습니다. 월 이용료에 디자인, 콘텐츠 작성, 호스팅, SSL, 유지보수, 플랜별 수정 횟수가 포함됩니다. 도메인은 your-brand.nextchain.site 같은 무료 주소를 쓰거나, 직접 구매하신 도메인을 연결할 수 있습니다. 스타터 플랜(월 39,000원)은 랜딩페이지 1개에 알맞고, 그로스 플랜(월 99,000원)은 블로그가 있는 최대 5페이지 웹사이트에 알맞습니다."]},{"heading":"같은 랜딩페이지인데 가격 차이가 큰 이유는 무엇인가요?","paragraphs":["기존 템플릿으로 만든 랜딩페이지와 처음부터 따로 디자인한 랜딩페이지는 작업량이 크게 다릅니다. 가격에 영향을 주는 요소는 디자인을 얼마나 맞춤 제작하는지, 누가 글을 쓰는지, 효과(애니메이션)가 얼마나 많은지, 연동할 도구가 몇 개인지, 인도 후 지원 기간이 얼마나 되는지입니다.","저렴하다고 나쁜 것은 아닙니다. 다만 모바일에서 빠르게 열리는지, 문의 폼이 올바른 곳으로 알림을 보내는지, 도메인에 대한 권한이 나에게 있는지는 반드시 확인하세요."]},{"heading":"일시 결제와 월 구독 중 무엇이 좋을까요?","paragraphs":["랜딩페이지를 한 번의 캠페인에만 쓴다면 일시 결제로 충분합니다. 장기적으로 고객을 받는 창구이고 가격, 프로모션, 이미지를 자주 바꿔야 한다면, 운영을 맡겨 주는 월 구독이 기술적인 부담을 덜어 줍니다."]},{"heading":"랜딩페이지 제작 업체를 고르기 전 체크리스트","bullets":["가격에 도메인, 호스팅, SSL이 포함되어 있나요?","무상 수정은 몇 회인가요? 이후에는 어떻게 비용을 받나요?","콘텐츠는 누가 작성하나요? 제가 미리 준비해야 하나요?","구글 애널리틱스를 설치하고 폼 제출을 측정해 주나요?","도메인은 누구 명의로 등록되나요?"]}]'::jsonb, '[{"q":"랜딩페이지를 아주 싸게 만들어 주는 업체가 있는 이유는 무엇인가요?","a":"기존 템플릿을 쓰거나, 글 작성을 해 주지 않거나, 수정 횟수가 적거나, 도메인·호스팅·유지보수를 비용에 넣지 않은 경우가 많습니다. 처음 가격만 보지 말고 1~2년간의 총비용으로 비교해 보세요."},{"q":"랜딩페이지 제작 비용에 광고 집행도 포함되나요?","a":"아니요. 구글이나 메타에 지불하는 광고비는 별도 비용입니다."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"랜딩페이지 제작 서비스"},{"href":"/bang-gia","label":"전체 서비스 요금 안내"},{"href":"/blog/landing-page-khac-website-doanh-nghiep","label":"랜딩페이지와 기업 웹사이트는 어떻게 다른가요?"}]'::jsonb, '2026-10-13', NULL),
('chi-phi-thiet-ke-landing-page', 'en', 'landing-page-design-cost', 'published', 'What Does Landing Page Design Cost Include? How to Calculate It, With a Checklist', 'Landing Page Design Cost', 'The costs of building a landing page: design, content, domain, hosting and maintenance. Compares paying once with a monthly plan and gives a checklist for choosing a provider.', 'Cost', '/blog/covers/project-4.jpg', 876, 493, 'The Nextchain Team', 6, 'Landing page cost is made up of design, content and development, a domain and hosting (paid every year), and the edits and maintenance that come afterwards. There are two ways to pay: once, then look after it yourself, or a monthly plan that includes design, hosting, updates and maintenance. Nextchain.site uses the monthly plan, from $29/month with no setup fee.', '["Don''t compare design prices alone. Ask about the domain, hosting, number of edits and how long support lasts.","A landing page for a short campaign can use a basic plan. A page that will run ads for a long time deserves tracking and conversion work.","Advertising spend is a separate cost and is not part of the design price."]'::jsonb, '[{"heading":"What costs make up a landing page?","bullets":["Design: layout, colors and images that match your brand.","Content: headline, benefits and calls to action. Many providers charge separately for writing.","Development and responsive layout: a page that looks right on phones and loads quickly.","Integrations: contact form, WhatsApp, Google Analytics, ad pixels and email marketing tools.","Domain and hosting: paid yearly, and either billed separately or bundled into a maintenance plan.","Edits and maintenance: how many free changes you get and how long support lasts after handover."]},{"heading":"What is each cost paying for?","table":{"head":["Item","When you pay","Notes"],"rows":[["Design & content","Once, at the start","Layout, copywriting and the number of design options"],["Domain","Yearly","Ask whose name the domain is registered under"],["Hosting & SSL","Monthly or yearly","Affects speed and reliability"],["Edits & updates","Per request or per plan","Number of free edits and turnaround time"],["Maintenance & backups","Recurring","Often forgotten when you pay once"]]}},{"heading":"How does Nextchain.site charge for a landing page?","paragraphs":["Nextchain.site sells landing pages on a monthly plan from $29, with no setup fee. The monthly fee covers design, content writing, hosting, SSL, maintenance and the number of edits in your plan. For a domain, you can use the free address your-brand.nextchain.site or buy your own and have Nextchain connect it. The Starter plan at $29/month suits a single landing page. The Growth plan at $79/month is for a website of up to 5 pages with a blog."]},{"heading":"Why do landing page prices vary so much?","paragraphs":["A landing page built from a ready-made template and one designed from scratch involve very different amounts of work. The factors that change the price are how much the design is customized, who writes the content, how many animations there are, how many tools need to be connected and how long support lasts after handover.","A low price is not necessarily a problem. Still, check that the page loads fast on a phone, that form submissions reach the right person, and that you control the domain."]},{"heading":"Pay once or pay monthly?","paragraphs":["If the landing page is for a single campaign, paying once is enough. If the page is a long-term way to get customers and you need to change content often (prices, promotions, images), a monthly management plan means you don''t have to deal with the technical side yourself."]},{"heading":"Checklist before choosing a landing page provider","bullets":["Does the price include the domain, hosting and SSL?","How many free edits do you get? How are further edits charged?","Who writes the content? Do you need to prepare it first?","Will they set up Google Analytics and track form submissions?","Whose name is the domain registered under?"]}]'::jsonb, '[{"q":"Why do some providers charge so little for a landing page?","a":"Often it is because they use ready-made templates, don''t write the content, offer few edits, or leave out the domain, hosting and maintenance. Compare the total cost over 1 to 2 years rather than just the starting price."},{"q":"Does the landing page price include running ads?","a":"No. The advertising budget you pay to Google or Meta is a separate cost."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"Landing page design service"},{"href":"/bang-gia","label":"Pricing for all services"},{"href":"/blog/landing-page-khac-website-doanh-nghiep","label":"How is a landing page different from a business website?"}]'::jsonb, '2026-10-13', NULL),
('landing-page-khac-website-doanh-nghiep', 'vi', 'landing-page-khac-website-doanh-nghiep', 'published', 'Landing page khác website doanh nghiệp như thế nào? Nên chọn loại nào', 'Landing page hay website doanh nghiệp?', 'So sánh landing page và website doanh nghiệp về mục tiêu, số trang, SEO, chi phí và thời gian. Hướng dẫn chọn theo mục tiêu kinh doanh.', 'So sánh', '/blog/covers/project-3.jpg', 876, 493, 'Đội ngũ Nextchain', 5, 'Landing page là một trang duy nhất phục vụ một mục tiêu cụ thể, thường là thu thông tin khách từ quảng cáo. Website doanh nghiệp gồm nhiều trang giới thiệu đầy đủ công ty, dịch vụ và tin tức, phù hợp để xây uy tín và nhận khách từ Google. Chạy quảng cáo cho một sản phẩm: chọn landing page; cần hiện diện lâu dài và SEO: chọn website.', '["Landing page tối ưu cho chuyển đổi; website tối ưu cho uy tín và SEO dài hạn.","Nhiều doanh nghiệp dùng cả hai: website làm nền, landing page cho từng chiến dịch.","Doanh nghiệp nhỏ mới bắt đầu có thể đi từ landing page rồi mở rộng thành website."]'::jsonb, '[{"heading":"Bảng so sánh landing page và website doanh nghiệp","table":{"head":["Tiêu chí","Landing page","Website doanh nghiệp"],"rows":[["Mục tiêu","Một hành động: để lại thông tin, gọi điện, đăng ký","Giới thiệu toàn diện, xây uy tín"],["Số trang","1 trang","5–15+ trang"],["Điều hướng","Hạn chế menu để khách không rời trang","Menu đầy đủ, nhiều trang con"],["SEO","Hạn chế, phù hợp vài từ khóa","Tốt hơn: mỗi dịch vụ một trang"],["Nội dung cần chuẩn bị","Ít: một thông điệp, một ưu đãi","Nhiều: từng dịch vụ, giới thiệu, bài viết"],["Chi phí tại Nextchain","Gói tháng từ 249.000đ, không phí khởi tạo","Theo dự án, từ 12.000.000đ"]]}},{"heading":"Khi nào nên chọn landing page?","bullets":["Chạy quảng cáo Google/Facebook cho một sản phẩm, khóa học, sự kiện.","Ra mắt dự án bất động sản, chương trình khuyến mãi có thời hạn.","Cơ sở nhỏ mới mở, cần nhanh chóng có trang nhận khách."]},{"heading":"Khi nào nên chọn website doanh nghiệp?","bullets":["Khách hàng (đặc biệt là B2B) cần tìm hiểu kỹ trước khi liên hệ.","Doanh nghiệp có nhiều dịch vụ, muốn khách tìm thấy từng dịch vụ trên Google.","Cần đăng tin tức, tuyển dụng, dự án thường xuyên."]},{"heading":"Có thể bắt đầu bằng landing page rồi nâng cấp không?","paragraphs":["Có. Nhiều cơ sở dịch vụ bắt đầu với một landing page để có mặt trên Google, sau đó bổ sung trang riêng cho từng dịch vụ và blog khi nhu cầu tăng. Điều quan trọng là giữ nguyên tên miền để không mất những gì đã xây dựng."]}]'::jsonb, '[{"q":"Landing page có lên Google được không?","a":"Có, nhưng vì chỉ có một trang nên thường chỉ phù hợp với tên thương hiệu và một vài từ khóa chính."},{"q":"Website doanh nghiệp có thay thế landing page khi chạy quảng cáo không?","a":"Có thể dẫn quảng cáo về trang dịch vụ trên website, nhưng landing page riêng thường cho tỉ lệ chuyển đổi tốt hơn vì ít yếu tố gây phân tán."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"Thiết kế landing page"},{"href":"/dich-vu/thiet-ke-website-doanh-nghiep","label":"Thiết kế website doanh nghiệp"},{"href":"/blog/chi-phi-thiet-ke-landing-page","label":"Chi phí thiết kế landing page"}]'::jsonb, '2026-10-13', NULL),
('landing-page-khac-website-doanh-nghiep', 'ko', 'landing-page-vs-business-website', 'published', '랜딩페이지와 기업 웹사이트는 어떻게 다른가요? 어떤 것을 선택해야 할까요', '랜딩페이지 vs 기업 웹사이트', '랜딩페이지와 기업 웹사이트를 목적, 페이지 수, SEO, 비용, 제작 기간으로 비교하고 사업 목표에 맞는 선택 방법을 안내합니다.', '비교', '/blog/covers/project-3.jpg', 876, 493, '넥스트체인 팀', 5, '랜딩페이지는 광고에서 유입된 고객의 정보를 받는 것처럼 한 가지 목표를 위한 한 페이지짜리 사이트입니다. 기업 웹사이트는 회사, 서비스, 소식을 여러 페이지로 충실히 소개하며 신뢰를 쌓고 구글 검색으로 고객을 받는 데 알맞습니다. 하나의 상품 광고를 집행한다면 랜딩페이지를, 오래 유지할 온라인 존재감과 SEO가 필요하다면 웹사이트를 선택하세요.', '["랜딩페이지는 전환에, 웹사이트는 신뢰와 장기적인 SEO에 최적화되어 있습니다.","많은 기업이 둘을 함께 씁니다. 웹사이트를 기본으로 두고 캠페인마다 랜딩페이지를 만드는 방식입니다.","이제 막 시작하는 소규모 사업자는 랜딩페이지로 시작해 웹사이트로 넓혀 갈 수 있습니다."]'::jsonb, '[{"heading":"랜딩페이지와 기업 웹사이트 비교표","table":{"head":["기준","랜딩페이지","기업 웹사이트"],"rows":[["목표","하나의 행동: 정보 남기기, 전화, 신청","전반적인 소개와 신뢰 구축"],["페이지 수","1페이지","5~15페이지 이상"],["내비게이션","고객이 이탈하지 않도록 메뉴를 최소화","전체 메뉴와 여러 하위 페이지"],["SEO","제한적, 몇 개의 키워드에 적합","더 유리: 서비스별로 페이지 구성"],["준비할 콘텐츠","적음: 메시지 하나, 혜택 하나","많음: 서비스별 설명, 소개, 글"],["넥스트체인 비용","월 39,000원부터, 초기 제작비 없음","프로젝트 단위, 1,900,000원부터"]]}},{"heading":"어떤 경우에 랜딩페이지를 선택하나요?","bullets":["하나의 상품, 강의, 행사를 위해 구글이나 페이스북 광고를 집행할 때.","분양 프로젝트나 기간 한정 프로모션을 알릴 때.","막 문을 연 작은 매장이 빠르게 고객을 받을 페이지가 필요할 때."]},{"heading":"어떤 경우에 기업 웹사이트를 선택하나요?","bullets":["고객(특히 B2B)이 연락하기 전에 꼼꼼히 알아보는 경우.","서비스가 여러 가지라서 각 서비스가 구글에서 따로 검색되길 원하는 경우.","소식, 채용, 프로젝트를 자주 게시해야 하는 경우."]},{"heading":"랜딩페이지로 시작해서 나중에 확장할 수 있나요?","paragraphs":["가능합니다. 많은 서비스 업체가 랜딩페이지 하나로 구글에 먼저 등장한 뒤, 수요가 늘면 서비스별 페이지와 블로그를 추가합니다. 중요한 것은 도메인을 그대로 유지해서 쌓아 온 것이 사라지지 않게 하는 것입니다."]}]'::jsonb, '[{"q":"랜딩페이지도 구글 검색에 노출될 수 있나요?","a":"가능합니다. 다만 페이지가 하나뿐이어서 보통 브랜드명과 몇 개의 주요 키워드에만 알맞습니다."},{"q":"광고를 집행할 때 기업 웹사이트가 랜딩페이지를 대신할 수 있나요?","a":"웹사이트의 서비스 페이지로 광고를 연결할 수도 있습니다. 다만 주의를 분산시키는 요소가 적기 때문에 별도의 랜딩페이지가 전환율이 더 좋은 경우가 많습니다."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"랜딩페이지 제작"},{"href":"/dich-vu/thiet-ke-website-doanh-nghiep","label":"기업 웹사이트 제작"},{"href":"/blog/chi-phi-thiet-ke-landing-page","label":"랜딩페이지 제작 비용"}]'::jsonb, '2026-10-13', NULL),
('landing-page-khac-website-doanh-nghiep', 'en', 'landing-page-vs-business-website', 'published', 'How Is a Landing Page Different From a Business Website? Which One to Choose', 'Landing Page or Business Website?', 'Compares a landing page and a business website on purpose, number of pages, SEO, cost and timeline, with guidance on choosing based on your business goal.', 'Comparison', '/blog/covers/project-3.jpg', 876, 493, 'The Nextchain Team', 5, 'A landing page is a single page built for one specific goal, usually collecting customer details from an ad. A business website has several pages that present the company, its services and news in full, which suits building credibility and getting customers from Google. Running ads for one product: choose a landing page. Need a lasting online presence and SEO: choose a website.', '["A landing page is built for conversions. A website is built for credibility and long-term SEO.","Many businesses use both: a website as the base and a landing page for each campaign.","A small business just starting out can begin with a landing page and expand it into a website later."]'::jsonb, '[{"heading":"Landing page vs. business website comparison","table":{"head":["Criteria","Landing page","Business website"],"rows":[["Goal","One action: leave details, call, sign up","A full introduction that builds credibility"],["Pages","1 page","5 to 15+ pages"],["Navigation","Minimal menu so visitors stay on the page","Full menu with many sub-pages"],["SEO","Limited, suited to a few keywords","Better: one page per service"],["Content to prepare","Little: one message, one offer","A lot: each service, an about page, articles"],["Cost at Nextchain","Monthly plan from $29, no setup fee","Per project, from $1,490"]]}},{"heading":"When should you choose a landing page?","bullets":["Running Google or Facebook ads for one product, course or event.","Launching a real estate project or a limited-time promotion.","A small business that has just opened and needs a page to get customers quickly."]},{"heading":"When should you choose a business website?","bullets":["Customers (especially B2B) research thoroughly before getting in touch.","You offer several services and want each one to be found on Google.","You need to post news, job openings or projects regularly."]},{"heading":"Can you start with a landing page and upgrade later?","paragraphs":["Yes. Many service businesses start with one landing page to appear on Google, then add a page for each service and a blog as demand grows. The important thing is to keep the same domain so nothing you have built is lost."]}]'::jsonb, '[{"q":"Can a landing page show up on Google?","a":"Yes, but with only one page it usually suits just the brand name and a few main keywords."},{"q":"Can a business website replace a landing page when running ads?","a":"You can send ads to a service page on your website, but a dedicated landing page usually converts better because it has fewer distractions."}]'::jsonb, '[{"href":"/dich-vu/thiet-ke-landing-page","label":"Landing page design"},{"href":"/dich-vu/thiet-ke-website-doanh-nghiep","label":"Business website design"},{"href":"/blog/chi-phi-thiet-ke-landing-page","label":"Landing page design cost"}]'::jsonb, '2026-10-13', NULL),
('website-spa-can-nhung-gi', 'vi', 'website-spa-can-nhung-gi', 'published', 'Website spa cần những trang và tính năng gì? Checklist cho chủ spa', 'Website spa cần những trang gì?', 'Danh sách trang và tính năng một website spa nên có: bảng dịch vụ, trang từng liệu trình, gallery, đặt hẹn, blog. Kèm lỗi thường gặp cần tránh.', 'Ngành Spa', '/blog/covers/spa.jpg', 1200, 800, 'Đội ngũ Nextchain', 6, 'Một website spa cần tối thiểu: trang chủ giới thiệu không gian và dịch vụ nổi bật, bảng dịch vụ có giá, trang riêng cho từng liệu trình chính, gallery ảnh thật và nút đặt hẹn qua form hoặc Zalo luôn hiển thị trên điện thoại. Blog chăm sóc da là phần bổ sung giúp spa xuất hiện nhiều hơn trên Google.', '["Khách spa ra quyết định dựa trên ba điều: có dịch vụ mình cần, giá khoảng bao nhiêu, cơ sở trông thế nào.","Mỗi liệu trình chính nên có trang riêng để khách tìm đúng trên Google.","Chỉ dùng ảnh thật của spa; ảnh trước/sau phải có sự đồng ý của khách."]'::jsonb, '[{"heading":"Các trang bắt buộc của website spa","table":{"head":["Trang","Nội dung chính","Mục đích"],"rows":[["Trang chủ","Không gian, dịch vụ nổi bật, địa chỉ, nút đặt hẹn","Ấn tượng đầu, dẫn khách đến đặt hẹn"],["Bảng dịch vụ","Liệu trình theo nhóm, thời lượng, giá","Trả lời câu hỏi “bao nhiêu tiền?”"],["Trang từng dịch vụ","Quy trình, lợi ích, lưu ý, giá","SEO theo từng dịch vụ"],["Gallery","Ảnh phòng trị liệu, đội ngũ, sản phẩm","Tạo niềm tin"],["Liên hệ / Đặt hẹn","Form, Zalo, bản đồ, giờ mở cửa","Chuyển đổi"]]}},{"heading":"Tính năng nên có","bullets":["Nút gọi và Zalo cố định ở góc màn hình điện thoại.","Form đặt hẹn ngắn: tên, số điện thoại, dịch vụ, thời gian mong muốn.","Bản đồ Google Maps và giờ mở cửa rõ ràng.","Tốc độ tải nhanh — ảnh được nén, không dùng video nặng ở đầu trang.","Thông tin khuyến mãi dễ thay đổi theo tháng."]},{"heading":"Lỗi thường gặp trên website spa","bullets":["Chỉ đăng ảnh mạng, không có ảnh thật của cơ sở.","Bảng giá đã cũ, khác giá thực tế khiến khách mất niềm tin.","Tất cả dịch vụ dồn vào một trang dài, khó đọc và khó lên Google.","Không ghi rõ địa chỉ, khách phải nhắn tin hỏi."]},{"heading":"Spa nhỏ có cần website khi đã có Facebook và Zalo?","paragraphs":["Facebook và Zalo tốt cho việc chăm sóc khách quen, nhưng bài đăng trôi nhanh và khó xuất hiện khi khách mới tìm “spa chăm sóc da gần đây” trên Google. Website là nơi tập trung thông tin cố định — dịch vụ, giá, địa chỉ — và là đích đến cho mọi kênh khác."]}]'::jsonb, '[{"q":"Website spa có cần chức năng đặt lịch tự động không?","a":"Với spa nhỏ, form yêu cầu hẹn kèm Zalo thường đủ dùng vì chủ spa vẫn cần xác nhận khung giờ. Đặt lịch tự động phù hợp khi có nhiều kỹ thuật viên và lịch dày."},{"q":"Có nên ghi giá dịch vụ trên website không?","a":"Nên ghi giá hoặc khoảng giá. Khách biết trước chi phí sẽ liên hệ với ý định rõ ràng hơn, giảm số tin nhắn chỉ hỏi giá."}]'::jsonb, '[{"href":"/giai-phap/website-spa","label":"Giải pháp website cho spa"},{"href":"/mau-website/spa","label":"Mẫu website spa"},{"href":"/bang-gia","label":"Bảng giá"}]'::jsonb, '2026-10-13', NULL),
('website-spa-can-nhung-gi', 'ko', 'spa-website-checklist', 'published', '스파 웹사이트에는 어떤 페이지와 기능이 필요할까요? 스파 사장님을 위한 체크리스트', '스파 웹사이트에 필요한 페이지', '스파 웹사이트가 갖춰야 할 페이지와 기능을 정리했습니다. 서비스 가격표, 프로그램별 페이지, 갤러리, 예약, 블로그와 함께 자주 하는 실수도 안내합니다.', '스파 업종', '/blog/covers/spa.jpg', 1200, 800, '넥스트체인 팀', 6, '스파 웹사이트에는 최소한 다음이 필요합니다. 공간과 대표 서비스를 소개하는 홈, 가격이 있는 서비스 안내표, 주요 프로그램별 전용 페이지, 실제 사진 갤러리, 그리고 모바일에서 항상 보이는 폼 또는 카카오톡 채널 예약 버튼입니다. 피부관리 블로그는 구글에서 더 많이 노출되도록 돕는 추가 요소입니다.', '["스파 고객은 세 가지를 보고 결정합니다. 원하는 서비스가 있는지, 가격이 대략 얼마인지, 매장이 어떤 모습인지입니다.","주요 프로그램마다 전용 페이지가 있어야 고객이 구글에서 정확히 찾을 수 있습니다.","스파의 실제 사진만 사용하세요. 시술 전후 사진은 고객의 동의를 받아야 합니다."]'::jsonb, '[{"heading":"스파 웹사이트에 꼭 필요한 페이지","table":{"head":["페이지","주요 내용","목적"],"rows":[["홈","공간, 대표 서비스, 주소, 예약 버튼","첫인상과 예약으로의 연결"],["서비스 안내표","그룹별 프로그램, 소요 시간, 가격","“얼마인가요?”라는 질문에 답하기"],["서비스별 페이지","진행 과정, 효과, 유의사항, 가격","서비스별 SEO"],["갤러리","관리실, 직원, 제품 사진","신뢰 형성"],["문의 / 예약","폼, 카카오톡 채널, 지도, 영업시간","전환"]]}},{"heading":"갖추면 좋은 기능","bullets":["모바일 화면 구석에 고정된 전화 버튼과 카카오톡 채널 버튼.","짧은 예약 폼: 이름, 전화번호, 서비스, 희망 시간.","구글 지도와 분명한 영업시간.","빠른 로딩 속도: 이미지를 압축하고, 페이지 맨 위에 무거운 영상을 두지 않기.","월별로 쉽게 바꿀 수 있는 프로모션 정보."]},{"heading":"스파 웹사이트에서 자주 하는 실수","bullets":["인터넷에서 가져온 사진만 쓰고 매장의 실제 사진이 없는 경우.","가격표가 오래되어 실제 가격과 달라서 고객의 신뢰를 잃는 경우.","모든 서비스를 긴 한 페이지에 몰아 넣어 읽기도 어렵고 구글 노출도 어려운 경우.","주소가 분명하지 않아 고객이 메시지로 물어봐야 하는 경우."]},{"heading":"작은 스파도 이미 SNS와 카카오톡 채널이 있는데 웹사이트가 필요한가요?","paragraphs":["SNS와 카카오톡 채널은 단골 고객을 관리하기에 좋습니다. 하지만 게시물은 빨리 묻히고, 새 고객이 구글에서 “근처 피부관리 스파”를 검색할 때 나타나기 어렵습니다. 웹사이트는 서비스, 가격, 주소처럼 변하지 않는 정보를 한곳에 모아 두는 곳이며, 다른 모든 채널이 향하는 목적지가 됩니다."]}]'::jsonb, '[{"q":"스파 웹사이트에 자동 예약 기능이 필요한가요?","a":"작은 스파라면 예약 요청 폼과 카카오톡 채널만으로도 충분한 경우가 많습니다. 시간대는 사장님이 직접 확인해야 하기 때문입니다. 자동 예약은 관리사가 많고 예약이 빽빽한 곳에 알맞습니다."},{"q":"웹사이트에 서비스 가격을 적는 것이 좋을까요?","a":"가격이나 가격대를 적는 것을 권합니다. 비용을 미리 아는 고객은 분명한 의사를 가지고 연락하기 때문에, 가격만 묻는 메시지가 줄어듭니다."}]'::jsonb, '[{"href":"/giai-phap/website-spa","label":"스파 웹사이트 솔루션"},{"href":"/mau-website/spa","label":"스파 웹사이트 템플릿"},{"href":"/bang-gia","label":"요금 안내"}]'::jsonb, '2026-10-13', NULL),
('website-spa-can-nhung-gi', 'en', 'spa-website-checklist', 'published', 'What Pages and Features Does a Spa Website Need? A Checklist for Spa Owners', 'What Pages Does a Spa Website Need?', 'The pages and features a spa website should have: a service menu, a page for each treatment, a gallery, booking and a blog. Includes common mistakes to avoid.', 'Spa', '/blog/covers/spa.jpg', 1200, 800, 'The Nextchain Team', 6, 'A spa website needs at least: a home page that shows the space and signature services, a service menu with prices, a dedicated page for each main treatment, a gallery of real photos, and a booking button (a form or WhatsApp) that stays visible on phones. A skincare blog is an extra that helps the spa show up more often on Google.', '["Spa customers decide on three things: whether you offer the service they want, roughly what it costs and what the place looks like.","Give each main treatment its own page so customers can find exactly that on Google.","Use only real photos of your spa. Before-and-after photos need the client''s consent."]'::jsonb, '[{"heading":"The essential pages of a spa website","table":{"head":["Page","Main content","Purpose"],"rows":[["Home","The space, signature services, address, booking button","First impression, leading visitors to book"],["Service menu","Treatments by group, duration, price","Answers the question “how much?”"],["Individual service pages","Process, benefits, notes, price","SEO for each service"],["Gallery","Treatment rooms, team, products","Builds trust"],["Contact / Booking","Form, WhatsApp, map, opening hours","Conversion"]]}},{"heading":"Features worth having","bullets":["Call and WhatsApp buttons fixed to the corner of the phone screen.","A short booking form: name, phone number, service and preferred time.","A Google Maps embed and clear opening hours.","Fast loading: compressed images and no heavy video at the top of the page.","Promotion details that are easy to change each month."]},{"heading":"Common mistakes on spa websites","bullets":["Using only stock photos from the internet with no real photos of the spa.","An outdated price list that differs from real prices, which costs customers'' trust.","Putting every service on one long page that is hard to read and hard to rank on Google.","Not stating the address clearly, so customers have to message to ask."]},{"heading":"Does a small spa need a website if it already has Facebook and WhatsApp?","paragraphs":["Facebook and WhatsApp work well for looking after regular customers, but posts get buried quickly and rarely appear when a new customer searches “skincare spa near me” on Google. A website is the one place for fixed information such as services, prices and address, and it is the destination for all your other channels."]}]'::jsonb, '[{"q":"Does a spa website need automatic online booking?","a":"For a small spa, a booking request form plus WhatsApp is often enough, since the owner still needs to confirm the time slot. Automatic booking suits spas with many therapists and a full schedule."},{"q":"Should I show service prices on the website?","a":"Yes, show the price or a price range. Customers who know the cost beforehand get in touch with clearer intent, and you get fewer messages that only ask about prices."}]'::jsonb, '[{"href":"/giai-phap/website-spa","label":"Website solution for spas"},{"href":"/mau-website/spa","label":"Spa website templates"},{"href":"/bang-gia","label":"Pricing"}]'::jsonb, '2026-10-13', NULL),
('lam-website-theo-goi-thang-hay-tra-mot-lan', 'vi', 'lam-website-theo-goi-thang-hay-tra-mot-lan', 'published', 'Làm website theo gói tháng hay trả tiền một lần: nên chọn cách nào?', 'Gói tháng hay trả một lần khi làm website?', 'So sánh hai cách làm website: trả một lần và thuê bao theo tháng. Ưu nhược điểm, chi phí ẩn và trường hợp phù hợp cho doanh nghiệp nhỏ.', 'Chi phí', '/blog/covers/cafe.jpg', 900, 1200, 'Đội ngũ Nextchain', 5, 'Trả một lần phù hợp khi bạn có người tự quản trị website hoặc ít khi cần thay đổi nội dung. Gói theo tháng phù hợp với chủ cơ sở bận rộn, muốn có người lo thiết kế, cập nhật, bảo trì và hỗ trợ kỹ thuật liên tục với chi phí đầu vào thấp hơn.', '["Website trả một lần vẫn phát sinh chi phí hằng năm: tên miền, hosting, sửa lỗi, cập nhật.","Gói tháng chuyển chi phí lớn ban đầu thành khoản đều đặn, kèm dịch vụ cập nhật.","Dù chọn cách nào, hãy hỏi rõ quyền sở hữu tên miền và nội dung khi ngừng hợp tác."]'::jsonb, '[{"heading":"So sánh nhanh","table":{"head":["Tiêu chí","Trả một lần","Gói theo tháng"],"rows":[["Chi phí ban đầu","Cao hơn","Thấp (chỉ phí tháng đầu tiên)"],["Cập nhật nội dung","Tự làm hoặc trả phí từng lần","Bao gồm theo phạm vi gói"],["Bảo trì, sao lưu","Tự lo hoặc thuê thêm","Bao gồm"],["Phù hợp","Có nhân sự kỹ thuật, ít thay đổi","Chủ cơ sở bận, cần thay đổi thường xuyên"]]}},{"heading":"Chi phí ẩn của website trả một lần","bullets":["Gia hạn tên miền và hosting hằng năm.","Sửa lỗi khi plugin, trình duyệt cập nhật.","Thay đổi giá, dịch vụ, hình ảnh khi không tự làm được.","Website cũ dần nhưng không ai cập nhật nội dung."]},{"heading":"Câu hỏi cần hỏi trước khi đăng ký gói tháng","bullets":["Mỗi tháng được bao nhiêu lượt cập nhật? Thời gian xử lý?","Có phí khởi tạo không? Cam kết tối thiểu bao lâu?","Hủy cần báo trước bao lâu? Nội dung và tên miền xử lý thế nào?","Phần việc ngoài gói được báo giá trước không?"]}]'::jsonb, '[{"q":"Gói tháng có đắt hơn về lâu dài không?","a":"Tùy cách so sánh. Nếu tính cả hosting, bảo trì và công cập nhật nội dung của website trả một lần, khoảng chênh thường nhỏ hơn bạn nghĩ. Hãy so sánh tổng chi phí trong 2–3 năm."},{"q":"Nextchain.site áp dụng hình thức nào?","a":"Landing page và website kinh doanh nhỏ: gói tháng từ 249.000đ, không phí khởi tạo, gồm cập nhật và bảo trì. Website doanh nghiệp, bán hàng và phần mềm: trả theo dự án, xem Bảng giá."}]'::jsonb, '[{"href":"/bang-gia","label":"Bảng giá dịch vụ và gói tháng"},{"href":"/dich-vu/quan-tri-website-theo-thang","label":"Quản trị website theo tháng"},{"href":"/chinh-sach-huy-dich-vu","label":"Chính sách hủy dịch vụ"}]'::jsonb, '2026-10-13', NULL),
('lam-website-theo-goi-thang-hay-tra-mot-lan', 'ko', 'monthly-plan-vs-one-time-website', 'published', '웹사이트 제작은 월 구독과 일시 결제 중 어떤 방법이 좋을까요?', '웹사이트 제작: 월 구독 vs 일시 결제', '웹사이트를 만드는 두 가지 방법인 일시 결제와 월 구독을 비교합니다. 장단점, 숨은 비용, 소규모 사업자에게 알맞은 경우를 설명합니다.', '비용', '/blog/covers/cafe.jpg', 900, 1200, '넥스트체인 팀', 5, '웹사이트를 직접 관리할 사람이 있거나 내용을 거의 바꿀 일이 없다면 일시 결제가 알맞습니다. 바쁜 사장님이 디자인, 업데이트, 유지보수, 기술 지원을 꾸준히 맡기고 싶다면, 초기 비용이 낮은 월 구독이 알맞습니다.', '["일시 결제로 만든 웹사이트도 도메인, 호스팅, 오류 수정, 업데이트 같은 비용이 매년 발생합니다.","월 구독은 큰 초기 비용을 매달 나누어 내는 방식이며, 업데이트 서비스가 함께 제공됩니다.","어느 쪽을 선택하든 계약이 끝났을 때 도메인과 콘텐츠의 소유권이 누구에게 있는지 분명히 물어보세요."]'::jsonb, '[{"heading":"한눈에 비교","table":{"head":["기준","일시 결제","월 구독"],"rows":[["초기 비용","더 높음","낮음 (첫 달 이용료만)"],["콘텐츠 업데이트","직접 하거나 건별로 비용 지불","플랜 범위 내에서 포함"],["유지보수·백업","직접 하거나 별도로 의뢰","포함"],["알맞은 경우","기술 인력이 있고 변경이 적음","바쁜 사장님, 자주 바꿔야 함"]]}},{"heading":"일시 결제 웹사이트의 숨은 비용","bullets":["도메인과 호스팅의 연간 갱신.","플러그인이나 브라우저가 업데이트될 때의 오류 수정.","직접 못 할 때 가격, 서비스, 이미지를 바꾸는 비용.","아무도 콘텐츠를 업데이트하지 않아 점점 낡아 가는 웹사이트."]},{"heading":"월 구독에 가입하기 전에 물어볼 질문","bullets":["매달 업데이트를 몇 번 해 주나요? 처리 시간은 얼마나 걸리나요?","초기 제작비가 있나요? 최소 약정 기간은 얼마인가요?","해지는 얼마나 미리 알려야 하나요? 콘텐츠와 도메인은 어떻게 되나요?","플랜 범위를 벗어난 작업은 진행 전에 견적을 받을 수 있나요?"]}]'::jsonb, '[{"q":"월 구독이 장기적으로 더 비싼가요?","a":"비교하는 방법에 따라 다릅니다. 일시 결제 웹사이트에 드는 호스팅, 유지보수, 콘텐츠 업데이트 작업까지 합하면 차이는 생각보다 작은 경우가 많습니다. 2~3년간의 총비용으로 비교해 보세요."},{"q":"넥스트체인은 어떤 방식으로 진행하나요?","a":"랜딩페이지와 소규모 사업자용 웹사이트는 월 39,000원부터 시작하는 월 구독이며, 초기 제작비가 없고 업데이트와 유지보수가 포함됩니다. 기업 웹사이트, 쇼핑몰, 소프트웨어는 프로젝트 단위로 진행하며, 자세한 내용은 요금 안내 페이지에서 확인하실 수 있습니다."}]'::jsonb, '[{"href":"/bang-gia","label":"서비스 및 월 구독 요금 안내"},{"href":"/dich-vu/quan-tri-website-theo-thang","label":"월 단위 웹사이트 운영"},{"href":"/chinh-sach-huy-dich-vu","label":"서비스 해지 정책"}]'::jsonb, '2026-10-13', NULL),
('lam-website-theo-goi-thang-hay-tra-mot-lan', 'en', 'monthly-plan-vs-one-time-website', 'published', 'Monthly Plan or One-Time Payment for a Website: Which Should You Choose?', 'Monthly Plan or Pay Once for a Website?', 'Compares two ways to get a website: paying once and paying monthly. Pros and cons, hidden costs and which suits a small business.', 'Cost', '/blog/covers/cafe.jpg', 900, 1200, 'The Nextchain Team', 5, 'Paying once suits you if someone on your side will manage the website or you rarely need to change the content. A monthly plan suits busy owners who want someone to handle design, updates, maintenance and technical support on an ongoing basis, with a lower upfront cost.', '["A website you pay for once still has yearly costs: the domain, hosting, bug fixes and updates.","A monthly plan turns a large upfront cost into a regular payment, with update services included.","Whichever you choose, ask who owns the domain and the content if you stop working together."]'::jsonb, '[{"heading":"Quick comparison","table":{"head":["Criteria","Pay once","Monthly plan"],"rows":[["Upfront cost","Higher","Low (only the first month''s fee)"],["Content updates","Do it yourself or pay each time","Included within the plan''s scope"],["Maintenance & backups","Handle yourself or hire separately","Included"],["Best for","Having technical staff and few changes","Busy owners who change things often"]]}},{"heading":"Hidden costs of a pay-once website","bullets":["Yearly renewal of the domain and hosting.","Fixing problems when plugins or browsers update.","Changing prices, services or images when you can''t do it yourself.","A website that slowly goes stale because nobody updates the content."]},{"heading":"Questions to ask before signing up for a monthly plan","bullets":["How many updates do you get each month? What is the turnaround time?","Is there a setup fee? What is the minimum commitment?","How much notice is needed to cancel? What happens to the content and domain?","Will work outside the plan be quoted before it starts?"]}]'::jsonb, '[{"q":"Is a monthly plan more expensive in the long run?","a":"It depends on how you compare. If you include the hosting, maintenance and time spent updating content on a pay-once website, the gap is often smaller than you expect. Compare total cost over 2 to 3 years."},{"q":"Which model does Nextchain.site use?","a":"Landing pages and websites for small businesses: a monthly plan from $29, with no setup fee, including updates and maintenance. Corporate websites, online stores and software: priced per project, see the Pricing page."}]'::jsonb, '[{"href":"/bang-gia","label":"Service and monthly plan pricing"},{"href":"/dich-vu/quan-tri-website-theo-thang","label":"Monthly website management"},{"href":"/chinh-sach-huy-dich-vu","label":"Cancellation policy"}]'::jsonb, '2026-10-13', NULL),
('website-hay-facebook-cho-kinh-doanh-nho', 'vi', 'website-hay-facebook-cho-kinh-doanh-nho', 'published', 'Đã có Fanpage Facebook, kinh doanh nhỏ có cần website không?', 'Đã có Fanpage, có cần website không?', 'So sánh Fanpage Facebook và website cho spa, salon, quán cà phê, homestay: khách tìm thấy bạn ở đâu, ai sở hữu dữ liệu, chi phí và khi nào nên làm website.', 'So sánh', '/blog/covers/nail.jpg', 1200, 800, 'Đội ngũ Nextchain', 5, 'Fanpage giúp giữ liên lạc với khách quen; website giúp khách mới tìm thấy bạn trên Google và tin tưởng trước khi liên hệ. Nếu khách của bạn thường tìm “spa gần đây”, “homestay Đà Lạt” hay xem bảng giá trước khi đến, nên có cả hai: website làm nơi thông tin chính thức, Fanpage để đăng bài và trò chuyện hằng ngày.', '["Fanpage và website không thay thế nhau — mỗi kênh giải quyết một việc khác.","Bài đăng Fanpage trôi theo thời gian; website giữ bảng giá, dịch vụ, địa chỉ luôn ở chỗ dễ tìm.","Website và tên miền là tài sản của bạn; Fanpage phụ thuộc chính sách của nền tảng.","Chi phí website cho cơ sở nhỏ hiện có thể bắt đầu từ 249.000đ/tháng, không cần trả một khoản lớn ban đầu."]'::jsonb, '[{"heading":"Fanpage và website khác nhau ở điểm nào?","table":{"head":["Tiêu chí","Fanpage Facebook","Website"],"rows":[["Khách mới tìm thấy bạn","Chủ yếu qua bạn bè chia sẻ, quảng cáo","Qua Google, Google Maps, link chia sẻ"],["Thông tin dịch vụ, bảng giá","Nằm trong bài đăng, dễ bị trôi","Có trang riêng, luôn ở vị trí cố định"],["Hình ảnh thương hiệu","Giao diện giống mọi Fanpage khác","Thiết kế riêng theo màu sắc, phong cách của bạn"],["Quyền sở hữu","Phụ thuộc chính sách và tài khoản Facebook","Bạn sở hữu tên miền và nội dung"],["Nhận yêu cầu","Tin nhắn, bình luận","Form, nút gọi, Zalo — gửi thẳng cho bạn"],["Chi phí","Miễn phí tạo, trả tiền nếu chạy quảng cáo","Phí thiết kế hoặc gói tháng, tên miền, hosting"]]}},{"heading":"Khi nào chỉ cần Fanpage là đủ?","bullets":["Bạn mới thử nghiệm sản phẩm, chưa có địa điểm hay bảng giá cố định.","Gần như toàn bộ khách đến từ người quen giới thiệu và nhắn tin trực tiếp.","Bạn chưa có thời gian trả lời yêu cầu từ kênh mới."]},{"heading":"Khi nào nên có website?","bullets":["Khách thường tìm trên Google trước khi chọn: spa, nha khoa, homestay, nhà hàng, trung tâm đào tạo.","Bạn chạy quảng cáo Google và cần một trang đích rõ ràng để đo hiệu quả.","Khách hỏi đi hỏi lại cùng một câu về giá, giờ mở cửa, địa chỉ.","Bạn muốn trông chuyên nghiệp hơn khi làm việc với đối tác, khách doanh nghiệp.","Bạn lo mất kênh liên lạc nếu tài khoản Fanpage gặp sự cố."]},{"heading":"Dùng website và Fanpage cùng nhau thế nào?","paragraphs":["Website là nơi đặt thông tin chính thức: dịch vụ, bảng giá, hình ảnh, địa chỉ, cách đặt lịch. Fanpage dùng để đăng bài mới, khuyến mãi và trò chuyện với khách.","Trong mỗi bài Fanpage, dẫn link về trang dịch vụ hoặc bảng giá trên website. Trên website, gắn nút Zalo, Facebook và form để khách chọn cách liên hệ quen thuộc."]},{"heading":"Website cho cơ sở nhỏ tốn bao nhiêu?","paragraphs":["Có hai cách phổ biến: trả một lần cho thiết kế rồi tự lo hosting, cập nhật; hoặc trả theo tháng với dịch vụ trọn gói. Nextchain.site áp dụng gói tháng từ 249.000đ, không phí khởi tạo, có địa chỉ miễn phí dạng ten-cua-ban.nextchain.site hoặc dùng tên miền riêng của bạn."]}]'::jsonb, '[{"q":"Có website rồi có nên bỏ Fanpage không?","a":"Không nên. Fanpage vẫn là kênh tốt để giữ liên lạc với khách quen và đăng nội dung hằng ngày. Website bổ sung phần khách mới tìm kiếm và thông tin chính thức."},{"q":"Website có giúp tôi lên Google Maps không?","a":"Google Maps hiển thị theo Hồ sơ doanh nghiệp trên Google (Google Business Profile). Gắn link website vào hồ sơ này giúp khách xem thêm thông tin và liên hệ dễ hơn."},{"q":"Tôi không rành công nghệ, có tự quản lý website được không?","a":"Với gói tháng của Nextchain, bạn chỉ cần gửi nội dung muốn thay đổi; đội ngũ Nextchain cập nhật theo số lượt của gói."}]'::jsonb, '[{"href":"/giai-phap","label":"Website theo ngành"},{"href":"/bang-gia","label":"Bảng giá gói tháng"},{"href":"/so-sanh/tu-lam-hay-thue-tron-goi","label":"Tự làm hay thuê trọn gói?"}]'::jsonb, '2026-10-15', NULL),
('website-hay-facebook-cho-kinh-doanh-nho', 'en', 'website-or-facebook-page', 'published', 'Already Have a Facebook Page: Does a Small Business Still Need a Website?', 'Have a Facebook Page, Need a Website?', 'Compares a Facebook Page and a website for spas, salons, cafes and homestays: where customers find you, who owns the data, cost and when to build a website.', 'Comparison', '/blog/covers/nail.jpg', 1200, 800, 'The Nextchain Team', 5, 'A Facebook Page helps you stay in touch with regular customers. A website helps new customers find you on Google and trust you before they get in touch. If your customers search for things like “spa near me” or “homestay in [city]”, or check prices before they visit, have both: the website as the official source of information and the Facebook Page for daily posts and conversation.', '["A Facebook Page and a website don''t replace each other. Each does a different job.","Facebook posts get pushed down over time. A website keeps your prices, services and address in a fixed, easy-to-find place.","The website and domain belong to you. A Facebook Page depends on the platform''s policies.","A website for a small business can now start from $29/month, with no large upfront payment."]'::jsonb, '[{"heading":"How are a Facebook Page and a website different?","table":{"head":["Criteria","Facebook Page","Website"],"rows":[["How new customers find you","Mostly through friends sharing and ads","Through Google, Google Maps and shared links"],["Service info and prices","Inside posts, easily buried","Dedicated pages in a fixed place"],["Brand image","Looks like every other Page","Designed around your own colors and style"],["Ownership","Depends on Facebook''s policies and your account","You own the domain and the content"],["Receiving inquiries","Messages and comments","Forms, call buttons and WhatsApp, sent straight to you"],["Cost","Free to create, paid if you run ads","Design fee or monthly plan, plus domain and hosting"]]}},{"heading":"When is a Facebook Page enough?","bullets":["You are still testing your product and have no fixed location or price list yet.","Almost all your customers come from referrals and message you directly.","You don''t yet have time to answer inquiries from a new channel."]},{"heading":"When should you have a website?","bullets":["Customers usually search Google before choosing: spas, dentists, homestays, restaurants, training centers.","You run Google ads and need a clear landing page to measure results.","Customers keep asking the same questions about prices, opening hours and address.","You want to look more professional when dealing with partners and business customers.","You worry about losing a channel if your Facebook Page account runs into problems."]},{"heading":"How do you use a website and a Facebook Page together?","paragraphs":["The website holds the official information: services, prices, photos, address and how to book. The Facebook Page is for new posts, promotions and talking with customers.","In each Facebook post, link to the service page or price page on your website. On the website, add WhatsApp and Facebook buttons and a form so customers can pick the way of contacting you that they are used to."]},{"heading":"How much does a website for a small business cost?","paragraphs":["There are two common ways: pay once for the design and then handle hosting and updates yourself, or pay monthly for a full-service plan. Nextchain.site offers monthly plans from $29, with no setup fee, a free address like your-brand.nextchain.site or your own domain."]}]'::jsonb, '[{"q":"If I have a website, should I drop my Facebook Page?","a":"No. A Facebook Page is still a good channel for staying in touch with regular customers and posting daily content. The website adds what new customers search for and your official information."},{"q":"Will a website help me show up on Google Maps?","a":"Google Maps shows listings from your Google Business Profile. Adding your website link to that profile helps customers see more information and get in touch more easily."},{"q":"I''m not technical. Can I manage a website myself?","a":"With a Nextchain monthly plan, you just send the changes you want and the Nextchain team makes the updates, within the number of edits in your plan."}]'::jsonb, '[{"href":"/giai-phap","label":"Websites by industry"},{"href":"/bang-gia","label":"Monthly plan pricing"},{"href":"/so-sanh/tu-lam-hay-thue-tron-goi","label":"DIY or done-for-you?"}]'::jsonb, '2026-10-15', NULL),
('website-nha-hang-khach-can-thay-gi', 'vi', 'website-nha-hang-khach-can-thay-gi', 'published', 'Website nhà hàng: khách cần thấy gì ngay khi mở trang?', 'Website nhà hàng cần có gì? Checklist', 'Khách mở website nhà hàng trên điện thoại cần thấy ngay món, giá, địa chỉ và cách đặt bàn. Checklist sắp xếp màn hình đầu, thực đơn, đặt bàn và chi nhánh.', 'Ngành Nhà hàng', '/blog/covers/project-1.jpg', 876, 493, 'Đội ngũ Nextchain', 6, 'Khi mở website nhà hàng, khách cần trả lời được bốn câu hỏi mà không phải cuộn nhiều: quán bán món gì, giá khoảng bao nhiêu, quán ở đâu và mở cửa lúc nào, đặt bàn bằng cách nào. Đặt bốn thông tin này ở màn hình đầu trên điện thoại, các phần còn lại như câu chuyện thương hiệu hay tiệc sự kiện để phía dưới.', '["Màn hình đầu trên điện thoại quan trọng nhất: món đặc trưng, khoảng giá, địa chỉ, giờ mở cửa và nút đặt bàn.","Thực đơn phải là chữ đọc được, có giá — không chỉ là ảnh chụp tờ menu.","Form đặt bàn nên hỏi ít: ngày, giờ, số khách, số điện thoại. Ghi rõ quán sẽ gọi hoặc nhắn Zalo để xác nhận.","Thông tin trên website phải khớp với Google Maps và Fanpage, nhất là giờ mở cửa và số điện thoại."]'::jsonb, '[{"heading":"Khách vào website nhà hàng để làm gì?","paragraphs":["Phần lớn khách mở website nhà hàng khi đã biết tên quán: thấy trên Google Maps, được bạn giới thiệu hoặc xem một bài đăng. Họ không cần đọc giới thiệu dài; họ đang kiểm tra nhanh xem quán có hợp với bữa ăn sắp tới không.","Vì vậy, website nhà hàng hiệu quả là website giúp khách quyết định nhanh và liên hệ dễ, chứ không phải website có nhiều hiệu ứng nhất."]},{"heading":"Màn hình đầu tiên trên điện thoại nên có gì?","bullets":["Ảnh món đặc trưng hoặc không gian thật của quán — không dùng ảnh mẫu trên mạng.","Một dòng mô tả quán bán gì: “Lẩu nấm và nướng than hoa”, “Cơm nhà kiểu Bắc”…","Khoảng giá tham khảo, ví dụ “150.000đ – 300.000đ/người”.","Địa chỉ ngắn và giờ mở cửa hôm nay.","Nút “Đặt bàn” và nút gọi hoặc Zalo luôn nhìn thấy, kể cả khi cuộn trang."]},{"heading":"Thực đơn nên trình bày thế nào?","table":{"head":["Nên làm","Nên tránh"],"rows":[["Chia nhóm: khai vị, món chính, lẩu, đồ uống…","Một danh sách dài không phân nhóm"],["Thực đơn dạng chữ, có giá từng món","Chỉ đăng ảnh chụp tờ menu (khó đọc, không phóng to được)"],["Ghi khẩu phần hoặc số người ăn với món lớn","Để khách đoán món đủ cho mấy người"],["Ảnh thật cho món bán chạy","Ảnh mạng không giống món thật"],["Ghi rõ ngày cập nhật giá","Giá cũ không ai sửa sau khi tăng giá"]]}},{"heading":"Đặt bàn: form, gọi điện hay Zalo?","paragraphs":["Với đa số nhà hàng nhỏ và vừa, không cần hệ thống đặt bàn tự động. Một form ngắn gửi về Zalo hoặc email của quán, kèm nút gọi điện, là đủ để quán chủ động xác nhận và sắp xếp chỗ."],"bullets":["Form chỉ hỏi: ngày, giờ, số khách, họ tên, số điện thoại, ghi chú (sinh nhật, ghế trẻ em…).","Ghi rõ sau khi gửi: “Quán sẽ gọi hoặc nhắn Zalo xác nhận trong 30 phút” — và làm đúng như vậy.","Đặt tiệc, đặt nhóm đông nên có mục riêng với set menu và sức chứa từng khu.","Nếu cần quản lý bàn trống hay đặt cọc online, đó là phần mềm riêng — nên tách khỏi website giới thiệu."]},{"heading":"Nhiều chi nhánh thì sắp xếp ra sao?","bullets":["Mỗi chi nhánh một mục hoặc một trang: địa chỉ, giờ mở cửa, số điện thoại, nút chỉ đường.","Nút đặt bàn hỏi rõ khách chọn chi nhánh nào.","Nếu thực đơn hoặc giá khác nhau giữa các chi nhánh, ghi chú rõ để tránh khách hiểu nhầm."]},{"heading":"Checklist trước khi đưa website nhà hàng lên mạng","bullets":["Mở website trên điện thoại: thấy món, giá, địa chỉ, giờ mở cửa và nút đặt bàn mà không cần cuộn nhiều.","Bấm thử nút gọi, nút Zalo, nút chỉ đường — tất cả mở đúng.","Gửi thử form đặt bàn và kiểm tra người phụ trách nhận được.","Giờ mở cửa, số điện thoại, địa chỉ khớp với Google Maps và Fanpage.","Giá trong thực đơn là giá hiện tại.","Có người chịu trách nhiệm cập nhật khi đổi món, đổi giá, nghỉ lễ."]},{"heading":"Làm website nhà hàng tốn bao nhiêu?","paragraphs":["Website giới thiệu nhà hàng với thực đơn, đặt bàn và chi nhánh không cần là dự án lớn. Nextchain.site làm theo gói tháng từ 249.000đ, không phí khởi tạo, gồm thiết kế, hosting và cập nhật thực đơn theo số lượt của gói. Bạn dùng miễn phí địa chỉ dạng ten-cua-ban.nextchain.site hoặc kết nối tên miền riêng."]}]'::jsonb, '[{"q":"Nhà hàng đã có Google Maps và Fanpage thì còn cần website không?","a":"Google Maps giúp khách tìm thấy quán, Fanpage giúp trò chuyện và đăng món mới. Website là nơi đặt thực đơn, giá, chi nhánh và đặt bàn ở dạng dễ đọc, và là đường link bạn gắn vào Google Maps để khách xem thêm."},{"q":"Có nên đăng ảnh chụp tờ menu lên website không?","a":"Có thể thêm, nhưng không nên chỉ có ảnh. Thực đơn dạng chữ dễ đọc trên điện thoại, phóng to được và cập nhật giá nhanh hơn."},{"q":"Website có nhận đặt cọc hoặc thanh toán online được không?","a":"Website giới thiệu thường chỉ nhận yêu cầu đặt bàn để quán xác nhận. Đặt cọc, thanh toán hay quản lý bàn trống cần hệ thống riêng và được báo giá theo dự án."}]'::jsonb, '[{"href":"/giai-phap/website-nha-hang","label":"Giải pháp website nhà hàng"},{"href":"/mau-website/nha-hang","label":"Mẫu website nhà hàng"},{"href":"/bang-gia","label":"Bảng giá gói tháng"}]'::jsonb, '2026-10-16', NULL),
('website-nha-hang-khach-can-thay-gi', 'ko', 'restaurant-website-essentials', 'published', '식당 웹사이트: 고객이 페이지를 열자마자 무엇을 봐야 할까요?', '식당 웹사이트에 필요한 것 체크리스트', '고객이 모바일로 식당 웹사이트를 열면 메뉴, 가격, 주소, 예약 방법이 바로 보여야 합니다. 첫 화면, 메뉴, 예약, 지점 구성을 위한 체크리스트를 안내합니다.', '식당 업종', '/blog/covers/project-1.jpg', 876, 493, '넥스트체인 팀', 6, '식당 웹사이트를 열면 고객은 많이 스크롤하지 않고도 네 가지 질문에 답을 얻어야 합니다. 어떤 메뉴를 파는지, 가격은 대략 얼마인지, 가게는 어디에 있고 언제 여는지, 예약은 어떻게 하는지입니다. 이 네 가지를 모바일 첫 화면에 두고, 브랜드 스토리나 단체 행사 같은 내용은 아래쪽에 두세요.', '["모바일 첫 화면이 가장 중요합니다. 대표 메뉴, 가격대, 주소, 영업시간, 예약 버튼이 있어야 합니다.","메뉴는 읽을 수 있는 텍스트로 가격과 함께 제공해야 합니다. 메뉴판 사진만 올려서는 안 됩니다.","예약 폼은 간단하게 날짜, 시간, 인원, 전화번호만 묻는 것이 좋습니다. 가게에서 전화나 카카오톡 채널 메시지로 확인한다고 분명히 안내하세요.","웹사이트의 정보는 구글 지도, 페이스북 페이지와 일치해야 합니다. 특히 영업시간과 전화번호가 그렇습니다."]'::jsonb, '[{"heading":"고객은 식당 웹사이트에 무엇을 하러 오나요?","paragraphs":["대부분의 고객은 가게 이름을 이미 알고 식당 웹사이트를 엽니다. 구글 지도에서 보았거나, 지인이 추천했거나, 게시물을 본 경우입니다. 이들은 긴 소개를 읽으려는 것이 아니라, 곧 있을 식사에 가게가 어울리는지 빠르게 확인하려는 것입니다.","그래서 효과적인 식당 웹사이트는 애니메이션 효과가 가장 많은 사이트가 아니라, 고객이 빨리 결정하고 쉽게 연락할 수 있는 사이트입니다."]},{"heading":"모바일 첫 화면에는 무엇이 있어야 하나요?","bullets":["대표 메뉴 사진이나 가게의 실제 공간 사진. 인터넷의 샘플 사진은 쓰지 마세요.","무엇을 파는 가게인지 한 줄 설명: “버섯 전골과 숯불구이”, “정갈한 집밥 한 상” 등.","참고용 가격대(예: 1인당 가격 범위).","짧은 주소와 오늘의 영업시간.","스크롤해도 계속 보이는 “예약” 버튼과 전화 또는 카카오톡 채널 버튼."]},{"heading":"메뉴는 어떻게 보여 주는 것이 좋을까요?","table":{"head":["이렇게 하세요","피하세요"],"rows":[["그룹으로 나누기: 전채, 메인, 전골, 음료 등","그룹 없이 이어지는 긴 목록"],["메뉴마다 가격이 있는 텍스트 메뉴","메뉴판 사진만 올리기 (읽기 어렵고 확대도 안 됨)"],["큰 메뉴는 양이나 몇 인분인지 표시","몇 명이 먹을 수 있는지 고객이 짐작하게 두기"],["인기 메뉴는 실제 사진 사용","실제 메뉴와 다른 인터넷 사진"],["가격을 업데이트한 날짜 표시","가격을 올린 뒤 아무도 고치지 않은 옛 가격"]]}},{"heading":"예약은 폼, 전화, 카카오톡 채널 중 무엇이 좋을까요?","paragraphs":["대부분의 소규모·중규모 식당에는 자동 예약 시스템이 필요하지 않습니다. 가게의 카카오톡 채널이나 이메일로 전달되는 짧은 폼과 전화 버튼이면, 가게가 먼저 확인하고 자리를 준비하기에 충분합니다."],"bullets":["폼에서는 날짜, 시간, 인원, 이름, 전화번호, 메모(생일, 아기 의자 등)만 물어보세요.","제출 후 “가게에서 30분 이내에 전화 또는 카카오톡 채널 메시지로 확인해 드립니다”처럼 안내하고, 그대로 지키세요.","단체 예약이나 행사 예약은 세트 메뉴와 구역별 수용 인원이 있는 별도 항목을 두세요.","빈 테이블 관리나 온라인 예약금이 필요하다면 이는 별도 소프트웨어입니다. 소개용 웹사이트와는 분리하는 것이 좋습니다."]},{"heading":"지점이 여러 곳이면 어떻게 구성하나요?","bullets":["지점마다 항목 또는 페이지를 따로 두고 주소, 영업시간, 전화번호, 길찾기 버튼을 넣으세요.","예약 버튼에서는 고객이 어느 지점인지 선택하게 하세요.","지점마다 메뉴나 가격이 다르다면 고객이 오해하지 않도록 분명히 적으세요."]},{"heading":"식당 웹사이트를 공개하기 전 체크리스트","bullets":["휴대폰으로 열었을 때 많이 스크롤하지 않고도 메뉴, 가격, 주소, 영업시간, 예약 버튼이 보이나요?","전화, 카카오톡 채널, 길찾기 버튼을 눌러 보고 모두 올바르게 열리는지 확인하세요.","예약 폼을 직접 제출해 보고 담당자가 받는지 확인하세요.","영업시간, 전화번호, 주소가 구글 지도와 페이스북 페이지와 일치하나요?","메뉴의 가격이 현재 가격인가요?","메뉴가 바뀌거나 가격이 오르거나 휴무일이 생길 때 업데이트할 담당자가 있나요?"]},{"heading":"식당 웹사이트 제작 비용은 얼마인가요?","paragraphs":["메뉴, 예약, 지점을 갖춘 식당 소개 웹사이트는 큰 프로젝트일 필요가 없습니다. 넥스트체인은 월 39,000원부터 시작하는 월 구독으로 제작하며, 초기 제작비가 없습니다. 디자인, 호스팅, 플랜별 횟수의 메뉴 업데이트가 포함됩니다. your-brand.nextchain.site 같은 무료 주소를 쓰거나 보유하신 도메인을 연결할 수 있습니다."]}]'::jsonb, '[{"q":"식당이 구글 지도와 페이스북 페이지가 있어도 웹사이트가 필요한가요?","a":"구글 지도는 고객이 가게를 찾도록 돕고, 페이스북 페이지는 대화와 신메뉴 소개를 돕습니다. 웹사이트는 메뉴, 가격, 지점, 예약을 읽기 쉬운 형태로 담는 곳이며, 구글 지도에 연결해 고객이 더 자세히 볼 수 있게 하는 링크가 됩니다."},{"q":"웹사이트에 메뉴판 사진을 올려도 되나요?","a":"추가할 수는 있지만 사진만 있어서는 안 됩니다. 텍스트 메뉴는 모바일에서 읽기 쉽고, 확대할 수 있으며, 가격을 빠르게 고칠 수 있습니다."},{"q":"웹사이트에서 예약금이나 온라인 결제를 받을 수 있나요?","a":"소개용 웹사이트는 보통 가게가 확인할 수 있도록 예약 요청만 받습니다. 예약금, 결제, 빈 테이블 관리에는 별도 시스템이 필요하며 프로젝트별로 견적을 드립니다."}]'::jsonb, '[{"href":"/giai-phap/website-nha-hang","label":"식당 웹사이트 솔루션"},{"href":"/mau-website/nha-hang","label":"식당 웹사이트 템플릿"},{"href":"/bang-gia","label":"월 구독 요금 안내"}]'::jsonb, '2026-10-16', NULL),
('website-nha-hang-khach-can-thay-gi', 'en', 'restaurant-website-essentials', 'published', 'Restaurant Website: What Should Customers See as Soon as the Page Opens?', 'What a Restaurant Website Needs: Checklist', 'A customer opening a restaurant website on a phone needs to see dishes, prices, address and how to book right away. A checklist for the first screen, menu, reservations and branches.', 'Restaurant', '/blog/covers/project-1.jpg', 876, 493, 'The Nextchain Team', 6, 'When a customer opens a restaurant website, they should get answers to four questions without much scrolling: what the restaurant serves, roughly what it costs, where it is and when it opens, and how to book a table. Put these four things on the first screen on mobile, and leave the rest, such as the brand story or private events, further down.', '["The first screen on mobile matters most: signature dishes, price range, address, opening hours and a booking button.","The menu must be readable text with prices, not just a photo of the printed menu.","Keep the booking form short: date, time, party size and phone number. State that the restaurant will call or message on WhatsApp to confirm.","Information on the website must match Google Maps and your Facebook Page, especially opening hours and phone number."]'::jsonb, '[{"heading":"Why do customers visit a restaurant website?","paragraphs":["Most customers open a restaurant website when they already know the name: they saw it on Google Maps, someone recommended it or they came across a post. They don''t want a long introduction. They are quickly checking whether the place fits their next meal.","So an effective restaurant website helps customers decide fast and get in touch easily. It doesn''t need the most animations."]},{"heading":"What should the first screen on mobile contain?","bullets":["A photo of a signature dish or the real dining space. Don''t use stock photos from the internet.","One line saying what the restaurant serves: “Mushroom hotpot and charcoal grill”, “Home-style cooking” and so on.","A rough price range, for example the usual spend per person.","A short address and today''s opening hours.","A “Book a table” button and a call or WhatsApp button that stay visible while scrolling."]},{"heading":"How should the menu be presented?","table":{"head":["Do","Avoid"],"rows":[["Group dishes: starters, mains, hotpot, drinks and so on","One long list with no groups"],["A text menu with a price for each dish","Only a photo of the printed menu (hard to read, can''t zoom)"],["Note portion size or how many people larger dishes serve","Making customers guess how many people a dish feeds"],["Real photos for bestsellers","Internet photos that don''t match the real dish"],["Show the date prices were last updated","Old prices that nobody fixed after a price increase"]]}},{"heading":"Reservations: form, phone call or WhatsApp?","paragraphs":["Most small and mid-sized restaurants don''t need an automated booking system. A short form that sends requests to the restaurant''s WhatsApp or email, plus a call button, is enough for the restaurant to confirm proactively and arrange seating."],"bullets":["The form only asks for: date, time, party size, name, phone number and a note (birthday, high chair and so on).","After submission, say something like “We''ll call or message you on WhatsApp within 30 minutes to confirm”, and do exactly that.","For parties and large groups, add a separate section with set menus and the capacity of each area.","If you need table management or online deposits, that is separate software. Keep it apart from the introduction website."]},{"heading":"How should a restaurant with several branches organize its site?","bullets":["Give each branch its own section or page: address, opening hours, phone number and a directions button.","Have the booking button ask which branch the customer wants.","If menus or prices differ between branches, note it clearly to avoid confusion."]},{"heading":"Checklist before putting a restaurant website online","bullets":["Open the site on a phone: you can see the dishes, prices, address, opening hours and booking button without much scrolling.","Tap the call, WhatsApp and directions buttons to check they all open correctly.","Submit a test booking and confirm the right person receives it.","Opening hours, phone number and address match Google Maps and your Facebook Page.","Prices on the menu are the current prices.","Someone is responsible for updating the site when dishes or prices change or the restaurant closes for a holiday."]},{"heading":"How much does a restaurant website cost?","paragraphs":["A restaurant website with a menu, reservations and branches doesn''t have to be a big project. Nextchain.site builds it on a monthly plan from $29, with no setup fee, including design, hosting and menu updates within the number of edits in your plan. You can use a free address like your-brand.nextchain.site or connect your own domain."]}]'::jsonb, '[{"q":"If a restaurant already has Google Maps and a Facebook Page, does it still need a website?","a":"Google Maps helps customers find you and a Facebook Page helps you chat and post new dishes. A website is where the menu, prices, branches and reservations sit in an easy-to-read form, and it is the link you add to Google Maps so customers can see more."},{"q":"Should I post a photo of the printed menu on the website?","a":"You can add one, but don''t rely on the photo alone. A text menu is easier to read on a phone, can be zoomed and makes price updates faster."},{"q":"Can the website take deposits or online payments?","a":"An introduction website usually only takes booking requests for the restaurant to confirm. Deposits, payments or table management need a separate system, quoted per project."}]'::jsonb, '[{"href":"/giai-phap/website-nha-hang","label":"Website solution for restaurants"},{"href":"/mau-website/nha-hang","label":"Restaurant website templates"},{"href":"/bang-gia","label":"Monthly plan pricing"}]'::jsonb, '2026-10-16', NULL),
('website-homestay-7-thong-tin-khach-can', 'vi', 'website-homestay-7-thong-tin-khach-can', 'published', '7 thông tin khách cần xem trước khi hỏi phòng homestay', 'Website homestay cần có gì? 7 thông tin', 'Khách hỏi phòng homestay cần biết giá theo đêm, sức chứa, ảnh thật, vị trí, tiện ích, chính sách và cách đặt. Checklist website homestay nhận khách trực tiếp.', 'Ngành Homestay', '/blog/covers/homestay.jpg', 1200, 1200, 'Đội ngũ Nextchain', 6, 'Trước khi nhắn hỏi phòng, khách muốn biết 7 điều: giá theo đêm, phòng ở được mấy người, ảnh thật từng phòng, vị trí và cách đi, tiện ích, chính sách nhận/trả phòng – cọc – hủy, và cách đặt. Website homestay trình bày đủ 7 điều này sẽ giảm tin nhắn hỏi đi hỏi lại và giúp bạn nhận khách đặt trực tiếp, bổ trợ cho các nền tảng đặt phòng.', '["Ghi giá theo đêm cho ngày thường và cuối tuần, kèm ghi chú phụ thu lễ Tết.","Mỗi loại phòng cần sức chứa, loại giường và ảnh thật riêng.","Chính sách cọc và hủy phải ghi rõ trước khi khách chuyển khoản.","Form hỏi phòng chỉ cần ngày đến, ngày đi, số khách và số điện thoại; trả lời qua Zalo nhanh nhất có thể."]'::jsonb, '[{"heading":"Vì sao homestay cần website khi đã có Booking, Airbnb?","paragraphs":["Các nền tảng đặt phòng giúp khách mới tìm thấy bạn, nhưng mỗi đơn đều mất phí hoa hồng và bạn khó giữ liên lạc với khách cũ. Website là nơi khách quay lại, khách được giới thiệu và khách xem Fanpage có thể đặt trực tiếp với bạn.","Website không thay thế nền tảng đặt phòng — nó bổ trợ, và chỉ hiệu quả khi trả lời đủ những câu khách vẫn thường nhắn hỏi."]},{"heading":"7 thông tin khách cần thấy trước khi hỏi phòng","table":{"head":["Thông tin","Nên trình bày thế nào"],"rows":[["1. Giá theo đêm","Giá ngày thường, cuối tuần; ghi chú phụ thu lễ Tết và giá thêm người"],["2. Sức chứa","Số khách tối đa, loại giường, có kê thêm nệm được không"],["3. Ảnh thật từng phòng","Ảnh phòng ngủ, phòng tắm, view — chụp ban ngày, không dùng ảnh mạng"],["4. Vị trí và cách đi","Khoảng cách tới trung tâm, đường cho ô tô hay chỉ xe máy, nút chỉ đường"],["5. Tiện ích","Bếp, BBQ, chỗ đậu xe, nước nóng, máy sưởi hoặc điều hòa, wifi"],["6. Chính sách","Giờ nhận/trả phòng, mức cọc, điều kiện hủy, trẻ em, thú cưng"],["7. Cách đặt","Form ngày đến – ngày đi – số khách, kèm nút Zalo và gọi điện"]]}},{"heading":"Trang phòng nên sắp xếp thế nào?","bullets":["Mỗi loại phòng một khối: tên phòng, ảnh, sức chứa, loại giường, giá theo đêm.","Nút “Hỏi phòng này” ngay dưới từng loại phòng, tự điền sẵn tên phòng vào form.","Nếu có nguyên căn cho nhóm, tách thành mục riêng với tổng sức chứa và giá nguyên căn.","Ghi rõ giá đã gồm gì: bữa sáng, nước uống, đưa đón — tránh khách hiểu nhầm khi thanh toán."]},{"heading":"Chính sách: viết rõ để tránh tranh cãi","paragraphs":["Phần lớn hiểu lầm giữa chủ homestay và khách đến từ cọc và hủy phòng. Ghi chính sách bằng câu ngắn, cụ thể, và nhắc lại khi xác nhận đặt phòng qua Zalo."],"bullets":["Giờ nhận phòng và trả phòng; có nhận sớm/trả muộn không, phụ thu thế nào.","Mức cọc giữ phòng và thời hạn chuyển cọc.","Hủy trước bao lâu thì được hoàn cọc, hủy sát ngày thì xử lý ra sao.","Quy định về trẻ em, thú cưng, hút thuốc, giờ yên tĩnh."]},{"heading":"Hỏi phòng: form hay Zalo?","paragraphs":["Nên có cả hai. Form giúp khách gửi đủ thông tin một lần (ngày đến, ngày đi, số khách); Zalo giúp trao đổi nhanh và gửi ảnh. Website homestay thường chỉ nhận yêu cầu để chủ nhà xác nhận phòng trống — nếu cần lịch phòng tự động hoặc thanh toán online, đó là hệ thống riêng."]},{"heading":"Checklist trước khi đưa website homestay lên mạng","bullets":["Mở trên điện thoại: thấy ngay ảnh đẹp nhất, giá từ bao nhiêu và nút hỏi phòng.","Mỗi loại phòng có đủ ảnh, sức chứa, giá.","Chính sách cọc và hủy nằm ở chỗ dễ thấy, không chỉ trong chân trang.","Gửi thử form hỏi phòng và kiểm tra Zalo/email nhận được.","Địa chỉ, số điện thoại khớp với Google Maps và các nền tảng đặt phòng.","Có người cập nhật giá theo mùa và ngày lễ."]},{"heading":"Làm website homestay tốn bao nhiêu?","paragraphs":["Website homestay giới thiệu phòng, tiện ích, chính sách và nhận yêu cầu hỏi phòng không cần là dự án lớn. Nextchain.site làm theo gói tháng từ 249.000đ, không phí khởi tạo, gồm thiết kế, hosting và cập nhật giá, ảnh theo số lượt của gói. Bạn dùng miễn phí địa chỉ dạng ten-cua-ban.nextchain.site hoặc kết nối tên miền riêng."]}]'::jsonb, '[{"q":"Website homestay có tự động hiện phòng trống không?","a":"Website giới thiệu thường không quản lý phòng trống. Khách gửi yêu cầu theo ngày, chủ nhà kiểm tra và xác nhận qua Zalo hoặc điện thoại. Lịch phòng tự động hoặc kết nối nền tảng đặt phòng là phần mềm riêng, báo giá theo dự án."},{"q":"Có nên ghi giá công khai trên website không?","a":"Nên ghi giá tham khảo theo đêm cho ngày thường và cuối tuần. Khách thấy giá trước sẽ hỏi phòng đúng nhu cầu hơn; giá lễ Tết có thể ghi “liên hệ” kèm thời gian áp dụng."},{"q":"Homestay nhỏ chỉ 2–3 phòng có cần website không?","a":"Có thể chỉ cần một trang: ảnh, từng phòng kèm giá, chính sách và nút hỏi phòng. Gói landing page một trang phù hợp với quy mô này."}]'::jsonb, '[{"href":"/giai-phap/website-homestay","label":"Giải pháp website homestay"},{"href":"/mau-website/homestay","label":"Mẫu website homestay"},{"href":"/bang-gia","label":"Bảng giá gói tháng"}]'::jsonb, '2026-10-16', NULL),
('website-homestay-7-thong-tin-khach-can', 'ko', 'homestay-website-7-things', 'published', '홈스테이 객실을 문의하기 전에 고객이 확인하고 싶은 7가지 정보', '홈스테이 웹사이트에 필요한 7가지 정보', '객실을 문의하는 고객은 1박 요금, 수용 인원, 실제 사진, 위치, 편의시설, 정책, 예약 방법을 알고 싶어 합니다. 직접 예약을 받는 홈스테이 웹사이트 체크리스트입니다.', '홈스테이 업종', '/blog/covers/homestay.jpg', 1200, 1200, '넥스트체인 팀', 6, '객실을 문의하기 전에 고객은 일곱 가지를 알고 싶어 합니다. 1박 요금, 몇 명이 묵을 수 있는지, 객실별 실제 사진, 위치와 가는 방법, 편의시설, 체크인/체크아웃·예약금·취소 정책, 그리고 예약 방법입니다. 이 일곱 가지를 갖춘 홈스테이 웹사이트는 반복되는 문의 메시지를 줄여 주고, 숙박 예약 플랫폼을 보완해 직접 예약을 받는 데 도움이 됩니다.', '["평일과 주말의 1박 요금을 적고, 성수기·공휴일 추가 요금도 함께 안내하세요.","객실 유형마다 수용 인원, 침대 종류, 실제 사진이 따로 필요합니다.","예약금과 취소 정책은 고객이 입금하기 전에 분명히 적어야 합니다.","객실 문의 폼에는 도착일, 출발일, 인원, 전화번호만 있으면 충분합니다. 카카오톡 채널로는 가능한 한 빨리 답변하세요."]'::jsonb, '[{"heading":"Booking, Airbnb가 있는데 홈스테이에 웹사이트가 왜 필요한가요?","paragraphs":["숙박 예약 플랫폼은 새 고객이 나를 찾도록 돕지만, 예약마다 수수료가 들고 이전 고객과 연락을 이어 가기 어렵습니다. 웹사이트는 다시 찾아오는 고객, 소개받은 고객, 페이스북 페이지를 본 고객이 나에게 직접 예약할 수 있는 곳입니다.","웹사이트가 예약 플랫폼을 대체하는 것은 아닙니다. 보완하는 역할이며, 고객이 자주 메시지로 묻는 질문에 충분히 답할 때만 효과가 있습니다."]},{"heading":"객실을 문의하기 전에 고객이 보고 싶은 7가지 정보","table":{"head":["정보","이렇게 보여 주세요"],"rows":[["1. 1박 요금","평일, 주말 요금. 성수기·공휴일 추가 요금과 인원 추가 요금도 함께 표시"],["2. 수용 인원","최대 인원, 침대 종류, 추가 침구 제공 가능 여부"],["3. 객실별 실제 사진","침실, 욕실, 전망 사진. 낮에 촬영하고 인터넷 사진은 쓰지 않기"],["4. 위치와 가는 방법","중심지까지의 거리, 자동차로 갈 수 있는지 오토바이 같은 이륜차만 가능한지, 길찾기 버튼"],["5. 편의시설","주방, 바비큐, 주차, 온수, 난방 또는 에어컨, 와이파이"],["6. 정책","체크인/체크아웃 시간, 예약금, 취소 조건, 어린이, 반려동물"],["7. 예약 방법","도착일·출발일·인원 폼과 카카오톡 채널, 전화 버튼"]]}},{"heading":"객실 페이지는 어떻게 구성하나요?","bullets":["객실 유형마다 한 블록씩: 객실 이름, 사진, 수용 인원, 침대 종류, 1박 요금.","각 객실 유형 바로 아래에 “이 객실 문의하기” 버튼을 두고, 폼에 객실 이름이 미리 입력되게 하세요.","단체용 독채가 있다면 총 수용 인원과 독채 요금이 있는 별도 항목으로 나누세요.","요금에 포함된 것을 분명히 적으세요. 조식, 생수, 픽업 등을 적어 두면 결제할 때의 오해를 막을 수 있습니다."]},{"heading":"정책: 분쟁을 막으려면 분명하게 쓰세요","paragraphs":["홈스테이 사장님과 고객 사이의 오해는 대부분 예약금과 취소에서 비롯됩니다. 정책은 짧고 구체적인 문장으로 쓰고, 카카오톡 채널로 예약을 확정할 때 한 번 더 안내하세요."],"bullets":["체크인과 체크아웃 시간. 일찍 체크인하거나 늦게 체크아웃할 수 있는지, 추가 요금은 얼마인지.","객실을 잡아 두기 위한 예약금 금액과 입금 기한.","언제까지 취소해야 예약금을 돌려받는지, 날짜가 임박해서 취소하면 어떻게 처리하는지.","어린이, 반려동물, 흡연, 정숙 시간에 대한 규정."]},{"heading":"객실 문의는 폼과 카카오톡 채널 중 무엇이 좋을까요?","paragraphs":["둘 다 두는 것이 좋습니다. 폼은 고객이 필요한 정보(도착일, 출발일, 인원)를 한 번에 보내게 해 주고, 카카오톡 채널은 빠른 대화와 사진 전송에 편리합니다. 홈스테이 웹사이트는 보통 요청만 받고 사장님이 빈 객실을 확인해 확정합니다. 자동 객실 캘린더나 온라인 결제가 필요하다면 별도 시스템이 필요합니다."]},{"heading":"홈스테이 웹사이트를 공개하기 전 체크리스트","bullets":["휴대폰으로 열었을 때 가장 예쁜 사진, 최저 요금, 객실 문의 버튼이 바로 보이나요?","객실 유형마다 사진, 수용 인원, 요금이 모두 있나요?","예약금과 취소 정책이 푸터에만 있지 않고 눈에 잘 띄는 곳에 있나요?","객실 문의 폼을 직접 제출해 보고 카카오톡 채널이나 이메일로 오는지 확인하세요.","주소와 전화번호가 구글 지도 및 숙박 예약 플랫폼과 일치하나요?","시즌과 공휴일에 맞춰 요금을 업데이트할 담당자가 있나요?"]},{"heading":"홈스테이 웹사이트 제작 비용은 얼마인가요?","paragraphs":["객실, 편의시설, 정책을 소개하고 객실 문의를 받는 홈스테이 웹사이트는 큰 프로젝트일 필요가 없습니다. 넥스트체인은 월 39,000원부터 시작하는 월 구독으로 제작하며, 초기 제작비가 없습니다. 디자인, 호스팅, 플랜별 횟수의 요금·사진 업데이트가 포함됩니다. your-brand.nextchain.site 같은 무료 주소를 쓰거나 보유하신 도메인을 연결할 수 있습니다."]}]'::jsonb, '[{"q":"홈스테이 웹사이트에 빈 객실이 자동으로 표시되나요?","a":"소개용 웹사이트는 보통 빈 객실을 관리하지 않습니다. 고객이 날짜로 요청을 보내면 사장님이 확인하고 카카오톡 채널이나 전화로 확정합니다. 자동 객실 캘린더나 숙박 예약 플랫폼 연동은 별도 소프트웨어이며 프로젝트별로 견적을 드립니다."},{"q":"웹사이트에 요금을 공개해도 될까요?","a":"평일과 주말의 1박 참고 요금을 적는 것을 권합니다. 요금을 미리 본 고객은 필요에 맞게 문의하게 됩니다. 성수기·공휴일 요금은 적용 기간과 함께 “문의”로 표시해도 됩니다."},{"q":"객실이 2~3개뿐인 작은 홈스테이도 웹사이트가 필요한가요?","a":"한 페이지면 충분할 수 있습니다. 사진, 객실별 요금, 정책, 객실 문의 버튼이 있으면 됩니다. 랜딩페이지 1페이지 플랜이 이 규모에 알맞습니다."}]'::jsonb, '[{"href":"/giai-phap/website-homestay","label":"홈스테이 웹사이트 솔루션"},{"href":"/mau-website/homestay","label":"홈스테이 웹사이트 템플릿"},{"href":"/bang-gia","label":"월 구독 요금 안내"}]'::jsonb, '2026-10-16', NULL),
('website-homestay-7-thong-tin-khach-can', 'en', 'homestay-website-7-things', 'published', '7 Things Guests Want to See Before Asking About a Homestay Room', 'Homestay Website: 7 Things Guests Need', 'Guests asking about a homestay room want the nightly rate, capacity, real photos, location, amenities, policies and how to book. A checklist for a homestay website that takes direct bookings.', 'Homestay', '/blog/covers/homestay.jpg', 1200, 1200, 'The Nextchain Team', 6, 'Before sending a message, guests want to know 7 things: the nightly rate, how many people the room sleeps, real photos of each room, the location and how to get there, amenities, check-in/check-out, deposit and cancellation policies, and how to book. A homestay website that covers all 7 cuts down on repeated messages and helps you win direct bookings alongside booking platforms.', '["List the nightly rate for weekdays and weekends, with a note on holiday surcharges.","Each room type needs its own capacity, bed type and real photos.","The deposit and cancellation policy must be stated before a guest transfers any money.","The room inquiry form only needs arrival date, departure date, number of guests and phone number. Reply on WhatsApp as fast as you can."]'::jsonb, '[{"heading":"Why does a homestay need a website when it is on Booking and Airbnb?","paragraphs":["Booking platforms help new guests find you, but every booking costs a commission and it is hard to stay in touch with past guests. A website is where returning guests, referred guests and people who saw your Facebook Page can book directly with you.","A website doesn''t replace booking platforms. It complements them, and it only works if it answers the questions guests usually message you about."]},{"heading":"7 things guests want to see before asking about a room","table":{"head":["Information","How to present it"],"rows":[["1. Nightly rate","Weekday and weekend rates; note holiday surcharges and extra-guest fees"],["2. Capacity","Maximum guests, bed types, whether an extra mattress can be added"],["3. Real photos of each room","Bedroom, bathroom and view, taken in daylight, no stock photos from the internet"],["4. Location and how to get there","Distance to the center, whether cars can get there or only motorbikes, a directions button"],["5. Amenities","Kitchen, BBQ, parking, hot water, heating or air conditioning, wifi"],["6. Policies","Check-in/check-out times, deposit amount, cancellation terms, children, pets"],["7. How to book","An arrival date, departure date and guest count form, plus WhatsApp and call buttons"]]}},{"heading":"How should the rooms page be laid out?","bullets":["One block per room type: room name, photos, capacity, bed type, nightly rate.","An “Ask about this room” button right under each room type, with the room name pre-filled in the form.","If you rent the whole property to groups, give it its own section with total capacity and the whole-property rate.","State what the rate includes: breakfast, drinking water, transfers. This avoids confusion at payment."]},{"heading":"Policies: write them clearly to avoid disputes","paragraphs":["Most misunderstandings between homestay owners and guests come from deposits and cancellations. Write the policies in short, specific sentences, and repeat them when you confirm a booking on WhatsApp."],"bullets":["Check-in and check-out times; whether early check-in or late check-out is possible and what it costs.","The deposit amount to hold a room and the deadline for sending it.","How far ahead a guest must cancel to get the deposit back, and what happens with last-minute cancellations.","Rules on children, pets, smoking and quiet hours."]},{"heading":"Room inquiries: form or WhatsApp?","paragraphs":["Offer both. A form lets guests send everything in one go (arrival date, departure date, number of guests), while WhatsApp is good for quick conversation and sending photos. A homestay website usually just takes requests so the owner can confirm availability. If you need an automatic room calendar or online payments, that is a separate system."]},{"heading":"Checklist before putting a homestay website online","bullets":["Open it on a phone: you immediately see the best photo, the starting rate and the room inquiry button.","Every room type has photos, capacity and a rate.","The deposit and cancellation policies are somewhere easy to see, not only in the footer.","Submit a test inquiry and confirm that it arrives on WhatsApp or email.","Address and phone number match Google Maps and your booking platforms.","Someone updates rates for seasons and holidays."]},{"heading":"How much does a homestay website cost?","paragraphs":["A homestay website that presents rooms, amenities and policies and takes room inquiries doesn''t have to be a big project. Nextchain.site builds it on a monthly plan from $29, with no setup fee, including design, hosting and updates to rates and photos within the number of edits in your plan. You can use a free address like your-brand.nextchain.site or connect your own domain."]}]'::jsonb, '[{"q":"Does a homestay website show available rooms automatically?","a":"An introduction website usually doesn''t manage availability. Guests send a request for their dates, and the owner checks and confirms on WhatsApp or by phone. An automatic room calendar or a connection to booking platforms is separate software, quoted per project."},{"q":"Should I show prices publicly on the website?","a":"Yes, show reference nightly rates for weekdays and weekends. Guests who see the price first ask about rooms that fit their needs. For holiday periods you can write “contact us” along with the dates it applies."},{"q":"Does a small homestay with just 2 to 3 rooms need a website?","a":"A single page may be enough: photos, each room with its rate, policies and a room inquiry button. The one-page landing page plan suits this size."}]'::jsonb, '[{"href":"/giai-phap/website-homestay","label":"Website solution for homestays"},{"href":"/mau-website/homestay","label":"Homestay website templates"},{"href":"/bang-gia","label":"Monthly plan pricing"}]'::jsonb, '2026-10-16', NULL),
('toi-uu-google-maps-cho-nha-hang-spa', 'vi', 'toi-uu-google-maps-cho-nha-hang-spa', 'published', 'Tối ưu Google Maps cho nhà hàng, spa: 7 việc chủ cơ sở tự làm được', 'Tối ưu Google Maps cho nhà hàng, spa', '7 việc giúp nhà hàng, spa, homestay hiện rõ hơn trên Google Maps: xác minh hồ sơ, chọn đúng danh mục, giờ mở cửa, ảnh thật, đánh giá, bài đăng và website.', 'Marketing', '/blog/covers/cafe.jpg', 900, 1200, 'Đội ngũ Nextchain', 7, 'Khách tìm “nhà hàng gần đây” hay “spa Quận 1” thường chọn quán ngay trên Google Maps. Để hồ sơ hiện rõ và được chọn, chủ cơ sở cần: xác minh Hồ sơ doanh nghiệp trên Google, chọn đúng danh mục chính, giữ giờ mở cửa chính xác, đăng ảnh thật, nhờ khách đánh giá và trả lời đánh giá, cập nhật bài đăng, và gắn website có đủ thông tin. Phần lớn việc này miễn phí và tự làm được.', '["Thứ hạng trên Google Maps phụ thuộc vào mức độ liên quan, khoảng cách và độ nổi bật của cơ sở — không mua được vị trí tự nhiên.","Tên trên hồ sơ phải đúng tên thật của cơ sở; nhồi từ khóa vào tên có thể khiến hồ sơ bị tạm ngưng.","Không mua đánh giá hay tặng quà đổi đánh giá 5 sao — đây là hành vi Google cấm.","Website có thực đơn, bảng giá, giờ mở cửa khớp với hồ sơ giúp khách quyết định nhanh hơn sau khi thấy bạn trên bản đồ."]'::jsonb, '[{"heading":"Google Maps xếp hạng cơ sở địa phương thế nào?","paragraphs":["Theo hướng dẫn công khai của Google, kết quả địa phương dựa chủ yếu vào ba yếu tố: mức độ liên quan (hồ sơ có khớp với điều khách tìm không), khoảng cách (cơ sở cách người tìm bao xa) và độ nổi bật (cơ sở được biết đến thế nào, gồm số lượng và chất lượng đánh giá, thông tin trên web).","Bạn không thay đổi được khoảng cách, nhưng làm được nhiều việc cho hai yếu tố còn lại. Bảy việc dưới đây đi theo đúng thứ tự nên làm."]},{"heading":"1. Tạo và xác minh Hồ sơ doanh nghiệp trên Google","bullets":["Vào business.google.com, tìm tên cơ sở — nếu đã có hồ sơ do người khác tạo, chọn yêu cầu quyền sở hữu thay vì tạo hồ sơ mới.","Hoàn tất bước xác minh theo cách Google đưa ra (video, điện thoại, email hoặc thư). Hồ sơ chưa xác minh bị hạn chế chỉnh sửa và hiển thị.","Dùng email công ty và thêm ít nhất một người quản lý dự phòng để không mất quyền truy cập."]},{"heading":"2. Điền đúng tên, danh mục và thông tin cơ bản","table":{"head":["Mục","Nên làm","Tránh"],"rows":[["Tên","Đúng tên trên biển hiệu","“Nhà hàng Hải Âu – Hải sản ngon rẻ nhất Q1”"],["Danh mục chính","Danh mục sát nhất: “Nhà hàng hải sản”, “Spa chăm sóc da”","Danh mục chung chung hoặc sai ngành"],["Danh mục phụ","Thêm vài danh mục đúng thực tế","Thêm danh mục không phục vụ"],["Địa chỉ, SĐT","Giống hệt website, Fanpage, biển hiệu","Mỗi nơi ghi một kiểu"],["Mô tả","Cơ sở phục vụ gì, cho ai, điểm khác biệt","Lặp từ khóa, chèn link, khuyến mãi"]]}},{"heading":"3. Giữ giờ mở cửa luôn chính xác","bullets":["Cập nhật giờ mở cửa thường ngày và giờ đặc biệt cho lễ, Tết trước vài ngày.","Khách đến nơi thấy đóng cửa trong khi Maps ghi đang mở là trải nghiệm tệ và dễ dẫn đến đánh giá xấu.","Nếu nghỉ tạm thời, dùng trạng thái tạm đóng cửa thay vì xóa hồ sơ."]},{"heading":"4. Đăng ảnh thật và cập nhật thường xuyên","bullets":["Ảnh mặt tiền giúp khách nhận ra quán khi đến nơi.","Ảnh không gian, món ăn hoặc dịch vụ thật, chụp đủ sáng — không dùng ảnh mạng.","Nhà hàng: thêm thực đơn hoặc ảnh món; spa: ảnh phòng dịch vụ; homestay: ảnh từng phòng.","Bổ sung ảnh mới định kỳ, nhất là khi đổi món, đổi không gian."]},{"heading":"5. Xin đánh giá đúng cách và trả lời mọi đánh giá","paragraphs":["Đánh giá là phần khách đọc nhiều nhất trước khi chọn quán. Hãy chủ động xin đánh giá từ khách thật bằng đường link đánh giá của hồ sơ (lấy trong trang quản lý hồ sơ), ví dụ in mã QR tại quầy hoặc gửi kèm tin nhắn cảm ơn."],"bullets":["Không mua đánh giá, không nhờ người quen viết đánh giá giả, không tặng quà để đổi đánh giá tốt.","Trả lời cả đánh giá tốt lẫn xấu, lịch sự và cụ thể. Với đánh giá xấu: xin lỗi, nêu cách khắc phục, mời liên hệ trực tiếp.","Không tranh cãi hay để lộ thông tin cá nhân của khách trong phần trả lời."]},{"heading":"6. Dùng bài đăng và thông tin sản phẩm, dịch vụ","bullets":["Đăng bài cập nhật: món mới, ưu đãi trong tháng, sự kiện — kèm ảnh và nút dẫn về website.","Điền mục sản phẩm/dịch vụ hoặc thực đơn với giá tham khảo nếu hồ sơ hỗ trợ.","Chọn các thuộc tính đúng thực tế: có chỗ đậu xe, có wifi, nhận thanh toán thẻ…"]},{"heading":"7. Gắn website có đủ thông tin và khớp với hồ sơ","paragraphs":["Nhiều khách bấm vào website từ hồ sơ Google Maps để xem kỹ thực đơn, bảng giá hoặc phòng trước khi gọi. Website cần trả lời ngay những điều đó trên điện thoại và có nút gọi, Zalo, đặt bàn hoặc đặt hẹn.","Tên, địa chỉ, số điện thoại và giờ mở cửa trên website phải giống hồ sơ Google. Thông tin nhất quán giữa các nơi giúp cả khách lẫn Google tin rằng đó là cùng một cơ sở."]},{"heading":"Checklist hằng tháng cho chủ cơ sở","bullets":["Giờ mở cửa và giờ lễ đã đúng chưa?","Đã trả lời hết đánh giá mới chưa?","Có ít nhất vài ảnh mới và một bài đăng trong tháng?","Thực đơn, bảng giá trên hồ sơ và website có khớp nhau?","Đường link website trên hồ sơ còn hoạt động?"]},{"heading":"Khi nào nên nhờ đơn vị làm thay?","paragraphs":["Nếu bạn không có thời gian cập nhật đều đặn, Nextchain có dịch vụ Marketing & SEO gồm tối ưu Hồ sơ doanh nghiệp trên Google, nội dung và báo cáo định kỳ. Với cơ sở chưa có website, gói tháng từ 249.000đ giúp bạn có trang thực đơn, bảng giá và đặt bàn để gắn vào Google Maps. Nextchain không cam kết thứ hạng cụ thể — thứ hạng do Google quyết định."]}]'::jsonb, '[{"q":"Có trả tiền để lên top Google Maps được không?","a":"Không mua được vị trí tự nhiên. Bạn có thể chạy quảng cáo Google để hiện ở vị trí quảng cáo, nhưng thứ hạng tự nhiên phụ thuộc vào mức độ liên quan, khoảng cách và độ nổi bật của cơ sở."},{"q":"Đặt từ khóa vào tên quán trên Google Maps có giúp lên hạng không?","a":"Không nên. Hướng dẫn của Google yêu cầu tên phản ánh đúng tên thật của cơ sở; thêm từ khóa có thể khiến hồ sơ bị chỉnh sửa hoặc tạm ngưng."},{"q":"Bao lâu thì thấy hồ sơ hiện tốt hơn?","a":"Không có mốc cố định. Thường cần vài tuần đến vài tháng cập nhật đều đặn và tích lũy đánh giá thật mới thấy thay đổi rõ."}]'::jsonb, '[{"href":"/dich-vu/marketing-seo","label":"Dịch vụ Marketing & SEO"},{"href":"/giai-phap/website-nha-hang","label":"Website nhà hàng"},{"href":"/giai-phap/website-spa","label":"Website spa"}]'::jsonb, '2026-10-16', NULL),
('toi-uu-google-maps-cho-nha-hang-spa', 'en', 'google-maps-for-restaurants-and-spas', 'published', 'Optimizing Google Maps for Restaurants and Spas: 7 Things Owners Can Do Themselves', 'Optimize Google Maps for Restaurants, Spas', '7 things that help restaurants, spas and homestays show up more clearly on Google Maps: verify your profile, pick the right category, opening hours, real photos, reviews, posts and a website.', 'Marketing', '/blog/covers/cafe.jpg', 900, 1200, 'The Nextchain Team', 7, 'People searching for “restaurants near me” or “spa near me” often choose a place straight from Google Maps. To make your listing show up and get chosen, you need to: verify your Google Business Profile, pick the right primary category, keep opening hours accurate, post real photos, ask customers for reviews and reply to them, update your posts, and link a website with complete information. Most of this is free and you can do it yourself.', '["Google Maps ranking depends on relevance, distance and prominence. You can''t buy an organic position.","The name on your profile must be your real business name. Stuffing keywords into the name can get the profile suspended.","Don''t buy reviews or give gifts in exchange for 5-star reviews. Google prohibits this.","A website with a menu, prices and opening hours that match your profile helps customers decide faster after they find you on the map."]'::jsonb, '[{"heading":"How does Google Maps rank local businesses?","paragraphs":["According to Google''s public guidance, local results are based mainly on three factors: relevance (how well your profile matches what the person searched for), distance (how far your business is from the searcher) and prominence (how well known your business is, including the number and quality of reviews and information on the web).","You can''t change distance, but you can do a lot for the other two. The seven steps below are in the order you should do them."]},{"heading":"1. Create and verify your Google Business Profile","bullets":["Go to business.google.com and search for your business name. If someone else has already created a profile for it, request ownership instead of creating a new one.","Complete the verification step Google offers (video, phone, email or postcard). An unverified profile has limited editing and visibility.","Use a business email and add at least one backup manager so you don''t lose access."]},{"heading":"2. Fill in the right name, category and basic details","table":{"head":["Field","Do","Avoid"],"rows":[["Name","Exactly the name on your sign","“Seaside Restaurant – Best and Cheapest Seafood Downtown”"],["Primary category","The closest match: “Seafood restaurant”, “Skin care spa”","A generic category or one from the wrong industry"],["Secondary categories","Add a few that accurately describe what you offer","Adding categories for services you don''t provide"],["Address, phone","Identical to your website, Facebook Page and sign","Writing it differently in each place"],["Description","What you offer, for whom, what makes you different","Repeated keywords, links, promotions"]]}},{"heading":"3. Keep opening hours accurate","bullets":["Update regular hours, and special hours for holidays a few days in advance.","A customer who arrives to find the place closed while Maps says it''s open has a bad experience and may leave a bad review.","If you close temporarily, use the temporarily closed status rather than deleting the profile."]},{"heading":"4. Post real photos and update them regularly","bullets":["A photo of the storefront helps customers recognize the place when they arrive.","Photos of the real space, food or services, taken in good light. No stock photos from the internet.","Restaurants: add the menu or photos of dishes. Spas: photos of treatment rooms. Homestays: photos of each room.","Add new photos from time to time, especially when you change the menu or the space."]},{"heading":"5. Ask for reviews the right way and reply to every review","paragraphs":["Reviews are what customers read most before choosing a place. Ask real customers for reviews using your profile''s review link (found in your profile management page), for example with a QR code printed at the counter or included in a thank-you message."],"bullets":["Don''t buy reviews, don''t ask friends to write fake ones and don''t give gifts in exchange for good reviews.","Reply to both good and bad reviews, politely and specifically. For a bad review: apologize, explain how you will fix it and invite them to contact you directly.","Don''t argue or reveal a customer''s personal information in your reply."]},{"heading":"6. Use posts and product or service listings","bullets":["Post updates: new dishes, offers this month, events, with a photo and a button linking to your website.","Fill in the products/services section or the menu with reference prices, if your profile supports it.","Choose attributes that are true for you: parking, wifi, card payments and so on."]},{"heading":"7. Link a website that has complete information and matches your profile","paragraphs":["Many customers tap the website link on a Google Maps profile to look at the menu, prices or rooms before calling. The website should answer those questions right away on a phone and have call, WhatsApp, booking or appointment buttons.","The name, address, phone number and opening hours on the website must match your Google profile. Consistent information across places helps both customers and Google trust that it is the same business."]},{"heading":"Monthly checklist for business owners","bullets":["Are your opening hours and holiday hours correct?","Have you replied to all new reviews?","Did you add at least a few new photos and one post this month?","Do the menu and prices on your profile and website match?","Does the website link on your profile still work?"]},{"heading":"When should you ask someone to do it for you?","paragraphs":["If you don''t have time to keep it updated, Nextchain offers a Marketing & SEO service that includes optimizing your Google Business Profile, content and regular reports. If you don''t have a website yet, a monthly plan from $29 gives you a page with your menu, prices and bookings to link from Google Maps. Nextchain does not promise any particular ranking, because Google decides rankings."]}]'::jsonb, '[{"q":"Can I pay to be at the top of Google Maps?","a":"You can''t buy an organic position. You can run Google ads to appear in the ad placements, but your organic ranking depends on relevance, distance and prominence."},{"q":"Does adding keywords to my business name on Google Maps help me rank?","a":"No, don''t do it. Google''s guidelines require the name to reflect your real business name, and adding keywords can get your profile edited or suspended."},{"q":"How long until my profile shows up better?","a":"There is no fixed timeline. It usually takes several weeks to several months of regular updates and a build-up of real reviews before you see a clear change."}]'::jsonb, '[{"href":"/dich-vu/marketing-seo","label":"Marketing & SEO service"},{"href":"/giai-phap/website-nha-hang","label":"Restaurant websites"},{"href":"/giai-phap/website-spa","label":"Spa websites"}]'::jsonb, '2026-10-16', NULL)
